_E2_PAIR_STATE = {}   # E2: persistent float32 pair-series buffers and their views (built once per process; n is fixed)


def _e2_pair_state(n):
    st = _E2_PAIR_STATE.get(n)
    if st is not None:
        return st
    f32 = fnp.float32
    PB = fnp.empty((7, n, n), dtype=f32)                 # [1, rho, rho^2/2!, ..., rho^6/6!]
    fnp.copyto(PB[0], 1.0)
