    alpha = aux['alpha']
    sigma = aux['sigma']
    g = aux['gate']
    eta = alpha / sigma
    half_d = 0.5 * d
    negative_half_g = (_e2_append_inline((_e2_value_inline := (-0.5))) or _e2_value_inline) * g
    negative_half_d = -half_d
    denominator = fnp.maximum((_e2_append_inline((_e2_value_inline := fnp.sum(_e2_append_inline((_e2_value_inline := (bp * bp))) or _e2_value_inline, axis=0))) or _e2_value_inline), 1e-20)
    _e2_hold.append(fnp.multiply(half_d[:, None], K21, out=D0))
