    if _BD_J1_PHYS is not None:   # PT-27 j05: leg j1 (row 1) in PHYSICAL form: not orthogonalized, coefficient _BD_J1_PHYS instead of c[1]
        _j1m = fnp.asarray([1.0, 0.0, 1.0], dtype=fnp.float64)   # J3CUT: three legs
