def _ps32(x):
    if (getattr(x, 'dtype', '')) == 'float32':
        return x
    owned = _E2_LAYER.get('post_cov32')
    if owned is not None and owned[0] is x:
        return owned[1]
    return fnp.asarray(x, dtype=fnp.float32)

def _ps_pre32(C):
    L = _E2_LAYER
    if L.get('Cpre') is C:
        if 'ps_Cpre32' not in L:
            L['ps_Cpre32'] = _ps32(C)
        return L['ps_Cpre32']
    return _ps32(C)

def _ps_k2132(K):
    L = _E2_LAYER
    if L.get('ps_K21') is not K:
        L['ps_K21'] = K
        L['ps_K2132'] = _ps32(K)
    return L['ps_K2132']

def _ps_target32(T):
    L = _E2_LAYER
    return L['ps_target32'] if L.get('ps_target64') is T else _ps32(T)
