    rowfill = _hz_slices([c for c in range(7) if c not in _HZ_ROW_FULL]) if hzr else []
    colfill = _hz_slices([c for c in range(7) if c not in _HZ_COL_FULL]) if hzc else []
    return mats, rowfill, colfill


