    H = (_e2_append_inline((_e2_value_inline := (_e2_append_inline((_e2_value_inline := fnp.stack([C['one'], aux['alpha'], aux['gate'], aux['pdf'], host, t, sigma, _e2_append_inline((_e2_value_inline := (t - s))) or _e2_value_inline]))) or _e2_value_inline)[:, selected])) or _e2_value_inline)
    H = (_e2_append_inline((_e2_value_inline := fnp.concatenate([H, _e2_append_inline((_e2_value_inline := fnp.power(_e2_append_inline((_e2_value_inline := H[6:])) or _e2_value_inline, -1.0))) or _e2_value_inline]))) or _e2_value_inline)                    # + 1 / sigma, 1 / gap
    A = (_e2_append_inline((_e2_value_inline := (C['coefA'] @ (_e2_append_inline((_e2_value_inline := fnp.prod(_e2_append_inline((_e2_value_inline := H[C['idxA']])) or _e2_value_inline, axis=0))) or _e2_value_inline)))) or _e2_value_inline)                     # one, u, w, 1 / v^2, S1..S4
    E = (_e2_append_inline((_e2_value_inline := (C['coefB'] @ (_e2_append_inline((_e2_value_inline := fnp.prod(_e2_append_inline((_e2_value_inline := A[C['idxB']])) or _e2_value_inline, axis=0))) or _e2_value_inline)))) or _e2_value_inline)
    _K4L_RAW[l] = E.astype(fnp.float32)
    _K4L_B[l] = fnp.unstack(_K4L_RAW[l])


