_HCF_STATE = dict(raw={}, ctx=None, rows15=None)
_HCF_CONST = {}
_HCF_STATS = dict(columns=0, used=0)
_HCF_AGES = (1.0, 1.0)   # column 18: the strengths of the cohorts aged 1, 2, .. (born at 14, 13, ..)


def _hcf_put(name, vector, mask, count):
    """A final-layer column's per-unit vector (float64), its unit mask (float64 0 / 1) and the number of its units."""
    if _HCF_U is None or name not in _HCF_COLUMNS:
        return
    _HCF_STATE['raw'][name] = (vector, mask, int(count))
    _HCF_STATS['columns'] += 1


_HCF_PARENT_L15 = _l15_rowcut_k3


def _l15_rowcut_k3(layer, mu, v, w32, p, previous, newborn, lam, state, star):
    _HCF_STATE['ctx'] = (layer, lam)
    try:
        return _HCF_PARENT_L15(layer, mu, v, w32, p, previous, newborn, lam, state, star)
    finally:
        _HCF_STATE['ctx'] = None


def _hcf_rows15(pp_rows, lam):
    """Columns 17 and 18 on the kept rows (vectors of the kept rows' length), from the pushed columns on those rows."""
    hold = _E2Hold()
    S = _NP_STATE
    out = {}
    want17, want18 = 'f15_diag' in _HCF_COLUMNS, 'f15_k31l_diag' in _HCF_COLUMNS
    if S['QX'] is None or not (want17 or want18):
        return out
    R = int(pp_rows.shape[1])
    sizes = S['sizes']
    if sum(sizes) != R or int(S['QX'].shape[1]) != R:
        raise RuntimeError('final-layer columns: weight roster')
    n = int(_HCF_CONST.get('n15') or 1024)
    C = _np_const(n)
    bounds, at = [], 0
    for width in sizes[:-1]:
        at += width
        bounds.append(at)
    blocks = hold(fnp.split(pp_rows, bounds, axis=1))
    swapped = hold(fnp.concatenate([blocks[i ^ 1] for i in range(len(blocks))], axis=1))           # every pair's two columns exchanged
    if want17:
        q, xq = hold(fnp.unstack(S['QX']))
        r2 = hold(pp_rows * q)
        hold(fnp.add(r2, hold(swapped * xq), out=r2))                                                # kap (q_r pp_ir + xq_r P_ir)
        out['f15_diag'] = hold(hold(hold(pp_rows * r2) @ lam).astype(fnp.float64))                     # kap B_ii on the kept rows
    if want18:
        ages = _HCF_AGES
        young, at, y0, y1 = [], 0, 0, 0
        for b, K in (S['births'] if ages else []):
            strength = ages[15 - b - 1] if 1 <= 15 - b <= len(ages) else 0.0
            if strength:
                if not young:
                    y0 = at
                y1 = at + 2 * K
            if young or strength:
                young.append((b, K, strength))
            at += 2 * K
        while young and not young[-1][2]:
            young.pop()
        if young:
            kept = int(pp_rows.shape[0])
            own = hold(pp_rows[:, y0:y1])
            delta = hold(own - hold(swapped[:, y0:y1]))
            dd = hold(delta * delta)
            means = hold(hold(fnp.stack([hold(fnp.sum(hold(own * own), axis=0)), hold(fnp.sum(hold(own * delta), axis=0)), hold(fnp.sum(dd, axis=0))])) * (1.0 / kept))
            lam_young = hold(lam[None, y0:y1])
            quartic = [(S['k4e'][b] if strength == 1.0 else hold(S['k4e'][b] * strength)) for b, _K, strength in young]
            quartic = quartic[0] if len(quartic) == 1 else hold(fnp.concatenate(quartic, axis=1))
            table = hold(fnp.concatenate([hold(fnp.power(lam_young, C['p01'])), hold(fnp.greater(lam_young, 0.0)), quartic, means]))
            c3, c2, c1, c0, c_o, c_d = hold(fnp.unstack(hold(C['coefK'] @ hold(fnp.prod(hold(table[C['idxK']]), axis=0)))))
            value = hold(own * c3)
            other = hold(delta * c2)
            hold(fnp.add(value, other, out=value)); hold(fnp.multiply(value, own, out=value))
            hold(fnp.multiply(dd, c1, out=other))
            hold(fnp.add(value, other, out=value)); hold(fnp.add(value, c_o, out=value)); hold(fnp.multiply(value, own, out=value))
            hold(fnp.multiply(dd, c0, out=other))
            hold(fnp.add(other, c_d, out=other)); hold(fnp.multiply(other, delta, out=other))
            hold(fnp.add(value, other, out=value))                                                   # (k31 / 3) x the plane's left factor / lam
            out['f15_k31l_diag'] = hold(hold(hold(value * own) @ hold(lam[y0:y1])).astype(fnp.float64))
    return out


_HCF_PARENT_K4L_LOCAL = _k4l_local


def _k4l_local(layer, pp, pp2, t3, state):
    if _HCF_U is not None and layer == 15 and _HCF_STATE['ctx'] is not None:
        _HCF_STATE['rows15'] = _hcf_rows15(pp, _HCF_STATE['ctx'][1])
    return _HCF_PARENT_K4L_LOCAL(layer, pp, pp2, t3, state)


_HCF_PARENT_K4L_FINAL = _k4l_final


def _k4l_final(mu, v):
    found = _K4L_FINAL[0]
    dk = _HCF_PARENT_K4L_FINAL(mu, v)
    found_rows15, _HCF_STATE['rows15'] = _HCF_STATE['rows15'], None
    if _HCF_U is None or found is None or found[1] is None:
        return dk
    hold = _E2Hold()
    rows = found[0]
    n, kept = int(v.shape[0]), int(rows.shape[0])
    mask = fnp.zeros(n, dtype=fnp.float64)
    fnp.put(mask, rows, 1.0)
    if 'f15_k4_local' in _HCF_COLUMNS and not isinstance(dk, float):
        _hcf_put('f15_k4_local', hold(dk / hold(v * v)), mask, kept)
    got = found_rows15 or {}
    if 'f15_diag' in got and kept >= 16:            # residual of the fit on (v, 1, mu^2) over the kept rows: G^-1 e_target times the rows
        K = _HCF_CONST
        if 'unit4' not in K:
            K['unit4'] = fnp.asarray([0.0, 0.0, 0.0, 1.0])
        vr, mr = hold(v[rows]), hold(mu[rows])
        X = hold(fnp.stack([vr, hold(fnp.ones(kept, dtype=fnp.float64)), hold(mr * mr), got['f15_diag']]))
        weights = hold(fnp.linalg.solve(hold(X @ hold(X.T)), K['unit4']))
        full = fnp.zeros(n, dtype=fnp.float64)
        fnp.put(full, rows, hold(hold(weights @ X) / vr))
        _hcf_put('f15_diag', hold(full), mask, kept)
    if 'f15_k31l_diag' in got:
        full = fnp.zeros(n, dtype=fnp.float64)
        fnp.put(full, rows, hold(got['f15_k31l_diag'] / hold(hold(v[rows]) * hold(v[rows]))))
        _hcf_put('f15_k31l_diag', hold(full), mask, kept)
    return dk


def _hcf_bias(bias):
    """enc0_b, or enc0_b + sum_k z_k u_k' with the final layer's columns (a column the network did not make counts as 0)."""
    present = dict(_HCF_STATE['raw'])
    _HCF_STATE['raw'] = {}
    if _HCF_U is None or not present:
        return bias
    hold = _E2Hold()
    K = _HCF_CONST
    n = int(next(iter(present.values()))[0].shape[0])
    if K.get('n') != n:
        K.update(n=n, u=fnp.asarray(_HCF_U, dtype=fnp.float32), zeros=fnp.zeros(n, dtype=fnp.float64))
    raw = [present.get(name, (K['zeros'], K['zeros'], n)) for name in _HCF_COLUMNS]
    M = hold(fnp.stack([mask for _, mask, _ in raw]))
    X = hold(hold(fnp.stack([hold(x) for x, _, _ in raw])) * M)
    inverse = hold(fnp.asarray([[1.0 / max(count, 1)] for _, _, count in raw]))
    root = hold(fnp.asarray([[max(count - 1.0, 0.0) ** 0.5] for _, _, count in raw]))
    centred = hold(hold(X - hold(hold(fnp.sum(X, axis=1, keepdims=True)) * inverse)) * M)
    scale = hold(hold(fnp.power(hold(fnp.maximum(hold(fnp.sum(hold(centred * centred), axis=1, keepdims=True)), 1e-300)), -0.5)) * root)
    Z = hold(hold(fnp.clip(hold(centred * scale), -8.0, 8.0)).astype(fnp.float32))
    _HCF_STATS['used'] += 1
    return bias + hold(fnp.einsum('kn,kc->nc', Z, K['u'], optimize=False))


_HCF_PARENT_HC_BIAS = _hc_bias


def _hc_bias(l, bias):
    out = _HCF_PARENT_HC_BIAS(l, bias)
    return _hcf_bias(out) if l == 15 else out
# END OPUS-ENGINEER FINAL-LAYER HEAD COLUMNS


# BEGIN OPUS-ENGINEER DEAD-CUT COVARIANCE SANDWICH (a44 dcv v3, 2026-10-10; an APPROXIMATION; lead 10-10 02:29Z / 03:0xZ). v3 = v2 with
# a choice of kernel for the second product W_a' (C_aa W_a) when the roster is cut (_DCV_SYM): 'generic' = _sym_upper's parent
# (two _mm products: 3/4 of the full product, about 190 requests; v1 / v2), 'pad' = the specialised 1,024 product (_psdb, 398
# requests) on W's rows in roster order with the cut operand padded by zero rows, 'tiles' = the specialised product's tiles
# (_psd_sym_tile: three 256-row rectangles, the diagonal blocks as (128, 64, 64)) at the inner size m. The same values up to
# rounding. v2 = v1 with
# the floor of the roster its own constant: _DCV_FLOOR (None = the live roster's floor, 0.01, v1). At 0.01 (v1) the cut units'
# covariances with the live ones carry 0.6-2e-3 of C_pre and the final-layer error rose 7-16% (RESULT.md section 32); at 1e-3
# (alpha -3.09) the cut drops 0.6-1.5e-4 (651: 75-151 units at layers 9-14, m 960 / 896), at Phi(-3.5) 0.6-1.0e-4 (95-121 units
# at layers 11-14, m 960; a44_cov/probe_deadcov_v3.py). v1 text follows.
# Every layer 1-15 pushes the post covariance C of the layer below through its weights: C_pre = W' C W (layers 1-14: the product
# C W, 1.01 Gflop, and the symmetric W' (C W), 0.71 Gflop, 9% of the bill together; layer 15: the diagonal alone, one C W). The
# units of the layer below outside its live roster (gate under the floor, 0.01) hold 1e-4 of C's trace; here their rows and columns
# of C are dropped. With a = the roster of the layer below (its units by gate as select() orders them, the count at or above the
# floor rounded up to a multiple of _DCV_ROUND, the size the products' kernels pad to anyway):
#     layers 1-14   C_pre = W_a' C_aa W_a          (the star part as the parent: _flms_cov_star's own lines)
#     layer 15      v     = the column sums of W_a o (C_aa W_a)
# A roster of the whole width runs the parent. What it drops on network 651 (a44_cov/probe_deadcov.py; live 992 .. 800 of 1,024 at
# layers 5-14, all 1,024 at layers 1-4): 0.6-2.0e-3 of C_pre's Frobenius norm, its diagonal 0.7-3.6e-4 rms, nearly all of it the
# cross covariances of the cut units with the live ones (the file's own float32 product is 1e-4 off).
_DCV_ROUND = 64
_DCV_FLOOR = 0.001
_DCV_SYM = 'pad'
_DCV_STATS = dict(cut=0, full=0, rows=0, m=0)


def _dcv_roster(gate, floor):
    """The units of the layer below the products keep, in select()'s order; None = all of them."""
    n = int(gate.shape[0])
    floor = floor if _DCV_FLOOR is None else _DCV_FLOOR
    m = min(n, (int(fnp.nonzero(gate >= floor)[0].shape[0]) + _DCV_ROUND - 1) // _DCV_ROUND * _DCV_ROUND)
    if m >= n:
        _DCV_STATS['full'] += 1
        return None
    _DCV_STATS['cut'] += 1
    _DCV_STATS['rows'] += m
    _DCV_STATS['m'] = m
    order = fnp.argsort(-gate, kind='stable')
    return order if _DCV_SYM == 'pad' else order[:m]


def _dc_cov_star(w, C, A, gate, floor, retain32=False):
    roster = _dcv_roster(gate, floor)
    if roster is None:
        return _flms_cov_star(w, C, A, retain32)
    if w.ndim != 2 or C.shape != (w.shape[0], w.shape[0]) or A.shape != (w.shape[0], w.shape[0]):
        raise ValueError('FLMS covariance/star shapes')
    if (w.dtype) != 'float32':
        raise TypeError('FLMS weights must be FP32')
    hold = _E2Hold()
    wt = w.T
    C32 = _ps32(C)
    A32 = A if (A.dtype) == 'float32' else A.astype(fnp.float32)
    wt2 = wt * wt
    P1, T2 = _ss_factors(wt, wt2, A32, hold)
    m = _DCV_STATS['m']
    if _DCV_SYM == 'pad':        # roster = the whole order; W's rows in that order, the cut operand padded with zero rows
        wp = hold(w[roster])
        wa = hold(wp[:m])
        live = hold(roster[:m])
        first = _mm(hold(C32[fnp.ix_(live, live)]), wa)
        s2 = _tsr_mm(T2, P1.T)
        cov = _sym_upper(hold(wp.T), hold(fnp.concatenate((first, hold(fnp.zeros((int(w.shape[0]) - m, int(w.shape[1])), dtype=fnp.float32))))))
    else:
        wa = hold(w[roster])
        first = _mm(hold(C32[fnp.ix_(roster, roster)]), wa)
        s2 = _tsr_mm(T2, P1.T)
        cov = _dcv_tiles(hold(wa.T), first, m) if _DCV_SYM == 'tiles' else _sym_upper(hold(wa.T), first)
    Cpre = cov.astype(fnp.float64)
    sub = s2 / 3
    diagonal = fnp.sum(hold(P1 * T2), axis=1, dtype=fnp.float64)
    result = sub.astype(fnp.float64)
    fnp.fill_diagonal(result, diagonal)
    _SS_STATS['planes'] += 1
    if retain32:
        fnp.fill_diagonal(sub, diagonal)
        return Cpre, result, cov, sub
    return Cpre, result


def _dc_cov_diagonal(w, C, gate, floor):
    roster = _dcv_roster(gate, floor)
    if roster is None:
        return _flms_covariance_diagonal(w, C)
    hold = _E2Hold()
    if _DCV_SYM == 'pad':
        roster = hold(roster[:_DCV_STATS['m']])
    wa = hold(w[roster])
    pushed = hold(_mm(hold(hold(_ps32(C))[fnp.ix_(roster, roster)]), wa))
    v = fnp.sum(hold(fnp.multiply(wa, pushed, dtype=fnp.float64)), axis=0)
    return v, v


def _dcv_tiles(A, B, m):
    """The upper blocks of A @ B for A = W_a' (1024, m), B = C_aa W_a (m, 1024): _psd_sym_upper's tiles at the inner size m."""
    if not (_AB_ON and _WINOGRAD and all(_ipt_fits(6, rows, m, cols) for rows, _k, cols in _PSD_SHAPES)):
        return _sym_upper(A, B)
    out = fnp.empty((1024, 1024), dtype=fnp.float32)
    for start in (0, 256, 512):
        end = start + 256
        _psd_sym_tile(A, B, out, start, 256, end, 1024 - end, False)
    for block in (0, 256, 512, 768):
        start = block
        for rows in _PSD_DIAGONAL:
            _psd_sym_tile(A, B, out, start, rows, start, block + 256 - start, True)
            start += rows
    return out
# END OPUS-ENGINEER DEAD-CUT COVARIANCE SANDWICH


