        cs = quad[(f,) * L + (slice(0, rm),) + (f,) * (L - 1) + (0, cm)] if hc else None
        cr = quad[(f,) * (L - 1) + (0, rm) + (f,) * (L - 1) + (0, cm)] if (hr and hc) else None
        rz = quad[(f,) * (L - 1) + (1, rm)] if hr else None
