# ASTRA bank-copy v1: HELD, source only, no native qualification.
# Requires pinned S56 XS plus UBcluster v1; independent of quarterload.
# Matrix calls, arithmetic/reduction order, ranks and tail repairs stay intact.
_ASTRA_BCC_ON = True
_ASTRA_BCC_CTX = [None]
_ASTRA_BCC_RIGHT = [None]
_ASTRA_BCC_STATS = dict(calls=0, expand_elements=0, join_elements=0,
                        outer_elements=0, destination_elements=0,
                        dcr_elements=0, rowmap_elements=0,
                        lazy_elements=0, newborn_elements=0)
_ASTRA_BCC_PARENT_EXPAND = _exact_expand_rows
_ASTRA_BCC_PARENT_PUSH = _OTT_ORIGINAL_PUSH
_ASTRA_BCC_PARENT_DEADCUT = _DCR_OLD_DEADCUT
_ASTRA_BCC_PARENT_RIGHT = _dcr_right
_ASTRA_BCC_PARENT_NEWBORN = _YNT_PARENT_PUSH
_ASTRA_BCC_PARENT_RECON = _slr_reconstruct
_ASTRA_BCC_PARENT_RECON_FULL = _OTT_ORIGINAL_RECON
_ASTRA_BCC_PARENT_PREDICT = _predict_binary


def _astra_bcc_capture(stage, call):
    ctx = _ASTRA_BCC_CTX[0]
    if ctx is None:
        return call()
    if ctx['stage'] is not None:
        raise RuntimeError('bank-copy nested capture')
    ctx['stage'] = stage
    ctx['parts'][stage] = None
    try:
        return call()
    finally:
        ctx['stage'] = None


def _exact_expand_rows(values, rows, total_rows):
    ctx = _ASTRA_BCC_CTX[0]
    if not _ASTRA_BCC_ON or ctx is None or ctx['stage'] not in ('old', 'young'):
        return _ASTRA_BCC_PARENT_EXPAND(values, rows, total_rows)
    stage = ctx['stage']
    if ctx['parts'][stage] is not None:
        raise RuntimeError('bank-copy repeated expansion in one captured result')
    kept, width = map(int, values.shape)
    if len(rows.shape) != 1 or int(rows.shape[0]) != kept or kept > total_rows:
        raise RuntimeError('bank-copy row ownership')
    if (values.dtype) != 'float32':
        raise TypeError('bank-copy original FP32 values required')
    ctx['parts'][stage] = (rows, int(total_rows))
    _ASTRA_BCC_STATS['expand_elements'] += kept * width
    return values


def _astra_bcc_scatter(out, values, inner_rows, outer_rows):
    hold = _BH_HOLD.append
    if inner_rows is None:
        rows = outer_rows
    elif outer_rows is None:
        rows = inner_rows
    else:
        rows = outer_rows[inner_rows]
        hold(rows)
        _ASTRA_BCC_STATS['rowmap_elements'] += int(inner_rows.shape[0])
    if rows is None:
        if tuple(out.shape) != tuple(values.shape):
            raise RuntimeError('bank-copy whole-block destination')
        hold(fnp.copyto(out, values))
    else:
        if int(rows.shape[0]) != int(values.shape[0]):
            raise RuntimeError('bank-copy scatter row ownership')
        hold(fnp.put_along_axis(out, rows[:, None], values, axis=0))
    _ASTRA_BCC_STATS['destination_elements'] += int(values.shape[0]) * int(values.shape[1])


def _astra_bcc_join(old, young, state):
    ctx = _ASTRA_BCC_CTX[0]
    if ctx is None:
        return fnp.concatenate([old, young], axis=1)
    m = ctx['compact_rows']
    oldcols = int(state['columns'])
    if int(old.shape[1]) != oldcols or (old.dtype) != (young.dtype) or (old.dtype) != 'float32':
        raise RuntimeError('bank-copy complete signed column blocks')
    pieces = []
    for name, values in (('old', old), ('young', young)):
        captured = ctx['parts'][name]
        if captured is None:
            if int(values.shape[0]) != m:
                raise RuntimeError('bank-copy uncropped row count')
            rows = None
        else:
            rows, total = captured
            if total != m:
                raise RuntimeError('bank-copy compact row universe')
        pieces.append(rows)
    width = oldcols + int(young.shape[1])
    answer = fnp.zeros((ctx['total_rows'], width), dtype=fnp.float32)
    _astra_bcc_scatter(answer[:, :oldcols], old, pieces[0], ctx['outer_rows'])
    _astra_bcc_scatter(answer[:, oldcols:], young, pieces[1], ctx['outer_rows'])
    _ASTRA_BCC_STATS['join_elements'] += m * width
    if ctx['outer_rows'] is not None:
        _ASTRA_BCC_STATS['outer_elements'] += m * width
        # DCR must retain its exact compact young block even when YNT cropped it.
        compact_young = young
        if pieces[1] is not None:
            compact_young = _ASTRA_BCC_PARENT_EXPAND(young, pieces[1], m)
            _ASTRA_BCC_STATS['dcr_elements'] += int(young.shape[0]) * int(young.shape[1])
        _ASTRA_BCC_RIGHT[0] = (compact_young, ctx['outer_rows'], answer, oldcols)
    ctx['done'] = True
    _ASTRA_BCC_STATS['calls'] += 1
    return answer


def _astra_bcc_lazy(mapped, U, rows, uv, columns):
    # One fresh compact destination, disjoint from both product inputs and scratch.
    left0 = mapped if rows is None else mapped[rows]
    left1 = U if rows is None else U[rows]
    nrows = int(left0.shape[0])
    if int(left1.shape[0]) != nrows:
        raise RuntimeError('bank-copy lazy row ownership')
    split = 2 * int(uv[1][0].shape[1])
    if split + 2 * int(uv[2][0].shape[1]) != columns:
        raise RuntimeError('bank-copy lazy full roster')
    answer = fnp.empty((nrows, columns), dtype=fnp.float32)
    _astra_bcc_uvrecon(left0, uv[1], answer[:, :split])
    _astra_bcc_uvrecon(left1, uv[2], answer[:, split:])
    _ASTRA_BCC_STATS['lazy_elements'] += nrows * columns
    return answer


def _astra_bcc_uvrecon(U, uv, out):
    """U (rows x rank) -> the t and s columns of every pair, roster order: U[:, :r_u] F_u +- U (F_v/2)."""
    Fu, Fv2, blocks, ru = uv
    rows = int(U.shape[0])
    Pu = _ubc_product(U[:, :ru], Fu, uv, 'u')
    Pv = _ubc_product(U, Fv2, uv, 'v')
    cols = 2 * int(Fu.shape[1])
    if tuple(out.shape) != (rows, cols) or (out.dtype) != 'float32':
        raise RuntimeError('bank-copy UV output ownership')
    h_ = _BH_HOLD.append
    b = 0
    views = _E2Hold()
    # Batch only complete, positive-width roster views; preserve generic fallback.
    tiled = bool(blocks) and int(blocks[0][0]) == 0
    end = 0; half_cuts = []; roster_cuts = []; packed = 0
    for start, width in blocks:
        tiled = tiled and int(start) == end and int(width) > 0
        end = int(start) + 2 * int(width)
        packed += int(width); half_cuts.append(packed)
        roster_cuts.extend((int(start) + int(width), end))
    tiled = tiled and end == int(out.shape[1])
    if tiled:
        pu_parts = views(fnp.split(Pu, half_cuts[:-1], axis=1))
        pv_parts = views(fnp.split(Pv, half_cuts[:-1], axis=1))
        out_parts = views(fnp.split(out, roster_cuts[:-1], axis=1))
    for index, (a, h) in enumerate(blocks):
        if tiled:
            pu, pv = pu_parts[index], pv_parts[index]
            op, om = out_parts[2 * index], out_parts[2 * index + 1]
        else:
            pu = views(Pu[:, b:b + h]); pv = views(Pv[:, b:b + h])
            op = views(out[:, a:a + h]); om = views(out[:, a + h:a + 2 * h])
        h_(fnp.add(pu, pv, out=op))
        h_(fnp.subtract(pu, pv, out=om))
        b += h
    if blocks: del pu, pv, op, om
    if tiled: del pu_parts, pv_parts, out_parts
    views.clear()
    _BH_HOLD.clear()
    del Pu, Pv
    return out


