def _peel_bind_read_io():
    if _PEEL_OWNER[0] is _SCRATCH[0]:
        return
    owner = fnp.empty((_PEEL_READ_MAX_A + _PEEL_READ_MAX_B,), dtype=fnp.float32)
    _PEEL_READ_IO.clear()
    for key in _PEEL_READ_PLANS:
        m,k,n,rank=key;total=k+rank
        A=fnp.reshape(owner[:m*total],(m,total))
        B=fnp.reshape(owner[_PEEL_READ_MAX_A:_PEEL_READ_MAX_A+total*n],(total,n))
        _PEEL_READ_IO[key]=(A,B,A[:,:k],B[:k,:],A[:,k:],B[k:,:])
    _PEEL_OWNER[:]=[_SCRATCH[0],owner]
    _PEEL_STATS['binds']+=1

_PEEL_TAIL_PLANS={}

def _peel_tail(a,b,recipe):
    m,k,n=int(a.shape[0]),int(a.shape[1]),int(b.shape[1])
    method,L=recipe
    if method=='dense':
        return fnp.matmul(a,b)
    if method!='shallower':
        return _mm(a,b)
    _TR_LAST[0]=None
    u=1<<L
    mm,kk,nn=((x+u-1)//u*u for x in (m,k,n))
    A=a;B=b
    if (m,k)!=(mm,kk):
        A=fnp.zeros((mm,kk),dtype=fnp.float32);fnp.copyto(A[:m,:k],a)
    if (k,n)!=(kk,nn):
        B=fnp.zeros((kk,nn),dtype=fnp.float32);fnp.copyto(B[:k,:n],b)
    out=fnp.empty((mm,nn),dtype=fnp.float32)
    _P6_OLD_IPAB(A,B,out,L)
    return fnp.copy(out[:m,:n]) if (m,n)!=(mm,nn) else out

def _peel_product(a,b,plan):
    record,family,m0,k0,n0=plan[:5]
    recipes=plan[5] if len(plan)>5 else (('parent',0),)*3
    m,k,n=int(a.shape[0]),int(a.shape[1]),int(b.shape[1])
    # Main result is owned: the SM40 final fnp.stack/reshape materializes it.
    main=_smx_call(record,family,a[:m0,:k0],b[:k0,:n0])
    assembled=m0<m or n0<n
    if assembled:
        answer=fnp.empty((m,n),dtype=fnp.float32)
        d00=answer[:m0,:n0]
        fnp.copyto(d00,main)
    else:
        answer=main;d00=answer
    if k0<k:
        tail=_peel_tail(a[:m0,k0:],b[k0:,:n0],recipes[0])
        fnp.add(d00,tail,out=d00)
    if n0<n:
        tail=_peel_tail(a[:m0,:],b[:,n0:],recipes[1])
        fnp.copyto(answer[:m0,n0:],tail)
    if m0<m:
        tail=_peel_tail(a[m0:,:],b,recipes[2])
        fnp.copyto(answer[m0:,:],tail)
    return answer

def _pushsm_mm(a,b):
    key=(int(a.shape[0]),int(a.shape[1]),int(b.shape[1]))
    plan=_PEEL_PUSH_PLANS.get(key)
    if (plan is None or not _AB_ON or not _WINOGRAD or not _SMX_ON or _SCRATCH is None
            or (a.dtype)!='float32' or (b.dtype)!='float32'):
        return _PEEL_PARENT_PUSH(a,b)
    if not _peel_take('push',key):return _PEEL_PARENT_PUSH(a,b)
    out=_peel_product(a,b,plan)
    _PEEL_STATS['push']+=1;_PEEL_STATS['push_shapes'].append(key)
    return out

def _peel_read(left,young_right,lam,live_indices,state):
    old=int(state['columns']);m,k,n=int(left.shape[0]),int(young_right.shape[1]),int(young_right.shape[0])
    rank=int(state['pre_basis'].shape[1])if old else 0
    key=(m,k,n,rank);plan=_PEEL_READ_PLANS.get(key)
    if (plan is None or not _AB_ON or not _WINOGRAD or not _SMX_ON or _SCRATCH is None
            or (left.dtype)!=(young_right.dtype)or (left.dtype)!='float32'
            or (lam.dtype)!='float32' or _ASTRA_RLF_CONTEXT[0]is not None
            or _UBX_CTX[0]is not None or _UBC_CONTEXT[0]is not None or _UBX_RC[0]is not None):
        return _PEEL_PARENT_READ(left,young_right,lam,live_indices,state)
    if not _peel_take('read',key):return _PEEL_PARENT_READ(left,young_right,lam,live_indices,state)
    _peel_bind_read_io()
    A,B,AY,BY,AO,BO=_PEEL_READ_IO[key]
    young=left[:,old:];young_lam=lam[old:]
    if m<n:
        fnp.multiply(young,young_lam,out=AY)
        fnp.copyto(BY,young_right.T)
    else:
        fnp.copyto(AY,young)
        fnp.multiply(young_right,young_lam,out=BY.T)
    if old:
        inner=_cp_slr_inner_sq(left[:,:old],lam[:old],state)
        right=_xsg_rows(5119,state['pre_basis'],live_indices)
        fnp.copyto(AO,inner);fnp.copyto(BO,right.T)
    out=_peel_product(A,B,plan)
    _PEEL_STATS['read']+=1;_PEEL_STATS['read_shapes'].append(key)
    return out
_RTT_PARENT_READ=_peel_read

def _astra_bcc_newborn_impl(w,p,previous,newborn):
    # E-48 --colpack E4: p is compact (its rows are previous), so no row gathers; the same products
    _e2_H = _E2Hold(); _e2_append_inline = _e2_H.append; _e2_value_inline = None   # E2: temporaries of this call, released together (one hidden free trip)
    wp = (_e2_append_inline((_e2_value_inline := _xsg_rows(5154, w, previous))) or _e2_value_inline).T   # opus-engineer a62 XSG: gather by scatter
    if newborn is None:
        return _mm(wp, (_e2_append_inline((_e2_value_inline := p)) or _e2_value_inline))
    old_columns,selected,base,t,s = newborn
    inherited = _pushsm_mm(wp, (_e2_append_inline((_e2_value_inline := p[:, :old_columns])) or _e2_value_inline))
    common = _w5_port_call(_W5_PORT_SCOPE,w,previous,'newborn_common',_mm,wp,_xsg_rows(5159, base, previous))   # opus-engineer a62 XSG
    _PHYS_HANDLES['newborn_common'] = common
    directions = (_e2_append_inline((_e2_value_inline := _xsg_rows(5161, w, selected))) or _e2_value_inline).T   # opus-engineer a62 XSG
    rows, births = int(common.shape[0]), int(common.shape[1])
    answer = fnp.empty((rows, int(old_columns) + 2 * births), dtype=fnp.float32)
    (_e2_append_inline((_e2_value_inline := fnp.copyto(answer[:, :int(old_columns)], inherited))) or _e2_value_inline)
    (_e2_append_inline((_e2_value_inline := fnp.add(common, _e2_append_inline((_e2_value_inline := (directions * t))) or _e2_value_inline, out=answer[:, int(old_columns):int(old_columns) + births]))) or _e2_value_inline)
    (_e2_append_inline((_e2_value_inline := fnp.add(common, _e2_append_inline((_e2_value_inline := (directions * s))) or _e2_value_inline, out=answer[:, int(old_columns) + births:]))) or _e2_value_inline)
    _ASTRA_BCC_STATS['newborn_elements'] += 2 * rows * births
    return answer


# Sequential peel products share existing main-read numeric owners. Static geometry only.
# Every returned product remains separately owned; transform caches invalidate as before.
def _smx_bind():
    env, arena = _SMX_ENV, _SCRATCH[0]
    base = _ASTRA_SM40_ENV
    assert base._sm40_owner is arena
    env._sm40_owner = None
    env._sm40_cache, env._sm40_io_cache, env._sm40_outer_cache, env._sm40_group_cache = {}, {}, {}, {}
    env._peel_batch_destination_cache = {}
    env._peel_batch_operand_cache = {}
    env._smx_prepared = None
    env._sm12_prepared = None
    env._sm40_frames = {name: _astra_sm40_bind_family(fnp, env, arena, f) for name, f in _SMX_FAMILIES.items()}
    dims = {name: (f[3] << f[1], f[4] << f[1], f[5] << f[1]) for name, f in _SMX_FAMILIES.items()}
    owners = sorted((fnp.reshape(x, (-1,)) for x in base._sm40_outer.values()), key=lambda x: int(x.shape[0]))
    pad = base._sm40_extra_leaf
    orientations = {}
    for plan in tuple(_PEEL_PUSH_PLANS.values()) + tuple(_PEEL_READ_PLANS.values()):
        orientations.setdefault(plan[1], set()).add(tuple(_SMX_RECORDS[plan[0]]['shape']))
    env._smx_outer, env._smx_padding = {}, {}
    for name, (r, k, c) in dims.items():
        shapes = dict(A=(40,r,k), B=(40,k,c), C=(40,r,c))
        ordered = sorted(shapes, key=lambda x: _rc_math.prod(shapes[x]))
        views = {}
        for side, owner in zip(ordered, owners):
            shape=shapes[side];count=_rc_math.prod(shape)
            assert count <= int(owner.shape[0]), (name,side,count,int(owner.shape[0]))
