# Fixed response-weighted rank4 W^3 message compression. W and GOP2 W^2 unchanged.
_W3R_METRIC = None
_W3R_STATS = dict(calls=0, metric_builds=0)

def _w3r_metric():
    global _W3R_METRIC
    if _W3R_METRIC is None:
        E = _GNN_PARAMS['enc0_w'][:, 62:78].astype(fnp.float64)
        values, vectors = fnp.linalg.eigh(fnp.matmul(E.T, E))
        scales = fnp.sqrt(fnp.maximum(values, 1e-30))
        root = fnp.matmul(vectors * scales[None, :], vectors.T)
        inverse = fnp.matmul(vectors / scales[None, :], vectors.T)
        _W3R_METRIC = (root, inverse)
        _W3R_STATS['metric_builds'] += 1
    return _W3R_METRIC

def _w3r_product(T, X):
    # ||(X-XLB) E.T||_F is minimized over rank4 XLB, for E=enc0[:,62:78].
    root, inverse = _w3r_metric()
    wide = X.astype(fnp.float64)
    gram = fnp.matmul(wide.T, wide)
    weighted = fnp.matmul(fnp.matmul(root, gram), root)
    _, vectors = fnp.linalg.eigh(weighted)
    V = vectors[:, -4:]
    L = fnp.matmul(root, V).astype(fnp.float32)
    B = fnp.matmul(V.T, inverse).astype(fnp.float32)
    coeff = fnp.matmul(X, L)
    projected = fnp.matmul(T, coeff)
    _W3R_STATS['calls'] += 1
    return fnp.matmul(projected, B)

def _gop2_message_product(T, X):
    n = int(X.shape[1]); assert X.shape == (3, n, 16)
    out = fnp.empty((3, n, 16), dtype=fnp.float32)
    fnp.matmul(T[0:1], X[0:1], out=out[0:1])
    fnp.copyto(out[1:2], _gop2_contract(T[1:2], X[1:2]))
    fnp.copyto(out[2], _w3r_product(T[2], X[2]))
    _GOP2_STATS['message_misses'] += 1
    return out




