# Static padding topology only. Public split creates the exact original strided
# rectangles. Alternating [start,end] boundaries return each interval at odd
# tuple positions, even when successive boundaries are non-monotone.
def _peel_split_ranges(owner, intervals, axis):
    extent = int(owner.shape[axis])
    intervals = tuple(sorted(set(intervals)))
    result = {}
    pending = []
    for interval in intervals:
        if interval == (0, extent):
            result[interval] = owner
        else:
            pending.append(interval)
    if pending:
        bounds = tuple(v for interval in pending for v in interval)
        parts = fnp.split(owner, bounds, axis=axis)
        for i, interval in enumerate(pending):
            result[interval] = parts[2*i+1]
    return result

def _peel_padding_rectangles(owner, rectangles):
    rectangles = tuple(sorted(set(rectangles)))
    sizes = tuple(map(int, owner.shape))
    def plan(axis):
        grouped = {}
        for r0,r1,c0,c1 in rectangles:
            intervals = ((r0,r1),(c0,c1))
            grouped.setdefault(intervals[axis], set()).add(intervals[1-axis])
        root = int(any(x != (0,sizes[axis]) for x in grouped))
        children = sum(any(x != (0,sizes[1-axis]) for x in values) for values in grouped.values())
        return root+children, axis, grouped
    _,axis,grouped = min((plan(0),plan(1)),key=lambda x:(x[0],x[1]))
    first = _peel_split_ranges(owner, grouped, axis)
    result = {}
    for interval, others in grouped.items():
        second = _peel_split_ranges(first[interval], others, 1-axis)
        for other, value in second.items():
            r,c = (interval,other) if axis == 0 else (other,interval)
            result[(r[0],r[1],c[0],c[1])] = value
    return result

def _peel_padding_specs():
    specs = {}
    for plan in tuple(_PEEL_PUSH_PLANS.values()) + tuple(_PEEL_READ_PLANS.values()):
        record,family,m,k,n = plan[:5]
        L = _SMX_FAMILIES[family][1];u = 1 << L
        ar,ak,an = _SMX_RECORDS[record]['shape']
        cm,ck,cn = (-(-x//(g*u))*u for x,g in zip((m,k,n),(ar,ak,an)))
        grid = (cm,ck,cn,ar,ak,an)
        dest = (m,k,n,0,cm,ck,cn,ar,ak,an)
        specs.setdefault(family,{})[(grid,dest)] = (m,k,n,cm,ck,cn,ar,ak,an)
    return specs

def _peel_prebind_padding():
    env = _SMX_ENV
    for family, specs in _peel_padding_specs().items():
        (fulla,fullb),grid_cache,dest_cache = env._smx_padding[family]
        needed = [set(),set()]
        recipes = []
        for (grid,dest),(m,k,n,cm,ck,cn,ar,ak,an) in specs.items():
            aa = (0,ar*cm,0,ak*ck);bb = (0,ak*ck,0,an*cn)
            av = tuple((i*cm,(i+1)*cm,j*ck,(j+1)*ck)for i in range(ar)for j in range(ak))
            bv = tuple((i*ck,(i+1)*ck,j*cn,(j+1)*cn)for i in range(ak)for j in range(an))
            ya=(0,m,0,k);yb=(0,k,0,n);zero=[]
            if m<ar*cm:zero.append((0,(m,ar*cm,0,ak*ck)))
            if k<ak*ck:zero.extend(((0,(0,m,k,ak*ck)),(1,(k,ak*ck,0,an*cn))))
            if n<an*cn:zero.append((1,(0,k,n,an*cn)))
            needed[0].update((aa,ya,*av));needed[1].update((bb,yb,*bv))
            for side,rect in zero:needed[side].add(rect)
            recipes.append((grid,dest,aa,bb,av,bv,ya,yb,zero))
        views = (_peel_padding_rectangles(fulla,needed[0]),_peel_padding_rectangles(fullb,needed[1]))
        for grid,dest,aa,bb,av,bv,ya,yb,zero in recipes:
            grid_cache[grid]=(views[0][aa],views[1][bb],tuple(views[0][x]for x in av),tuple(views[1][x]for x in bv))
            dest_cache[dest]=(views[0][ya],views[1][yb],None,None,tuple(views[side][rect]for side,rect in zero))


def _peel_prebind_batch_io(ker, key):
    """Populate the existing bb_batch cache; public view APIs only.

    Requires the existing side and outer caches. No arithmetic or new buffer.
    `key` is exactly (family, L, cm, ck, cn, P), as in outer_cache.
    """
    env = ker.M
    fnp = ker.fnp
    cache = env._sm40_io_cache
    LA, RB, PC, _, parts = env._sm40_outer_cache[key]
    if all((key, i) in cache for i in range(len(parts))):
        return
    family, L, m, k, n, P = key
    u = 1 << L
    TA, XA, GA, basA, opsA = ker.side(0, L, P, m, k)
    TB, XB, GB, basB, opsB = ker.side(1, L, P, k, n)
    TC, XC, GC, basC, opsC = ker.side(2, L, P, m, n)
    # These two destination views depend on side geometry, not chunk index.
    dcache = getattr(env, '_peel_batch_destination_cache', None)
    if dcache is None:
        dcache = env._peel_batch_destination_cache = {}
    ka, kb = (family, L, P, m, k, 0), (family, L, P, k, n, 1)
    if ka not in dcache:
        dcache[ka] = fnp.moveaxis(GA[0:3:2], 0, L + 1)
    if kb not in dcache:
        dcache[kb] = fnp.moveaxis(GB[0:3:2], 0, 1)
    dA, dB = dcache[ka], dcache[kb]
    total = int(LA.shape[0])
    assert total % P == 0 and len(parts) == total // P
    cuts = tuple(range(P, total, P))
    ocache = getattr(env, '_peel_batch_operand_cache', None)
    if ocache is None:
        ocache = env._peel_batch_operand_cache = {}
    chunks = ()
    # For a fixed family, each operand always comes from the same outer
    # owner; a change in the third matrix dimension cannot change these views.
    for side, owner, rows, cols in ((0, LA, m, k), (1, RB, k, n), (2, PC, m, n)):
        operand_key = (family, L, P, rows, cols, side)
        if operand_key not in ocache:
            V = fnp.reshape(owner, (total,) + (2,) * L + (rows // u,) + (2,) * L + (cols // u,))
            if side == 0:
                first, lower = fnp.unstack(V, axis=1)
                v21, v22 = fnp.unstack(lower, axis=L + 1)
                arrays = (first, v21, v22)
            elif side == 1:
                first, right = fnp.unstack(V, axis=L + 2)
                v12, v22 = fnp.unstack(right, axis=1)
                arrays = (first, v12, v22)
            else:
                upper, lower = fnp.unstack(V, axis=1)
                v11, v12 = fnp.unstack(upper, axis=L + 1)
                v21, v22 = fnp.unstack(lower, axis=L + 1)
                arrays = (v11, v12, v21, v22)
            ocache[operand_key] = tuple(tuple(fnp.split(x, cuts, axis=0)) for x in arrays) if cuts else tuple((x,) for x in arrays)
        chunks += ocache[operand_key]
    common = (TA, TB, TC, XA[1], XB[1], XC[1], basA, basB, basC, opsA, opsB, opsC)
    for i, vs in enumerate(zip(*chunks)):
        cache[(key, i)] = common + (dA, vs[0], vs[1], vs[2], dB, vs[3], vs[4], vs[5], tuple(vs[6:]))


# Compile only fixed Python argument routing; preserve every public numeric operation.
class _Sm40Prepared(tuple):
    def __new__(cls, value):
        obj=tuple.__new__(cls,value);obj.programs={};return obj
_LINEAR_PARENT_GROUPED=_astra_sm40_linear_grouped
def _astra_sm40_linear_grouped(fnp, plan, inputs, shape, stats, out=None, prepared=None):
    if not isinstance(prepared,_Sm40Prepared):
        return _LINEAR_PARENT_GROUPED(fnp,plan,inputs,shape,stats,out=out,prepared=prepared)
    key=(id(plan),id(inputs),id(out));program=prepared.programs.get(key)
    if program is None:
        input_refs,groups,output_refs,uses=plan;batches,node_views=prepared
        values={ref:inputs[i] for ref,i in input_refs.items()};ops=[];node_at=0;peak=0;scalar_bytes=_rc_math.prod(shape)*4
        operations={'add':fnp.add,'sub':fnp.subtract,'scale':fnp.multiply,'neg':fnp.multiply}
        for group_index,((depth,op,lit),nodes) in enumerate(groups):
            left=[values[args[0]] for ref,args in nodes]
            right=[values[args[1]] for ref,args in nodes] if op in ('add','sub') else None
            if len(nodes)==1:
                lhs=left[0];rhs=right[0] if right else -1 if op=='neg' else lit;destination=node_views[node_at]
            else:
                lhs=left;rhs=right if right else -1 if op=='neg' else lit;destination=batches[group_index]
            ops.append((operations[op],lhs,rhs,destination))
            for index,(ref,args) in enumerate(nodes):values[ref]=node_views[node_at+index]
            node_at+=len(nodes);peak=max(peak,2*len(nodes)*scalar_bytes)
        program=(inputs,out,tuple(ops),tuple(values[ref] for ref in output_refs),peak)
        if len(prepared.programs)>=16:prepared.programs.clear()
        prepared.programs[key]=program
    _,_,ops,outputs,peak=program;held=[]
    for operation,lhs,rhs,destination in ops:held.append(operation(lhs,rhs,out=destination))
    answer=fnp.stack(outputs,axis=0,**{} if out is None else {'out':out})
    stats['temp_peak']=max(stats['temp_peak'],peak);stats['temp_live']=0
    return answer

def _sm40_wrap_group_views(parent):
    def group_views(self,kind,shape):
        value=parent(self,kind,shape)
        if not isinstance(value,_Sm40Prepared):
            value=_Sm40Prepared(value);self.M._sm40_group_cache[self.record['name'],kind,tuple(shape)]=value
        return value
    return group_views
_AstraSm40Kernel.group_views=_sm40_wrap_group_views(_AstraSm40Kernel.group_views)
