# Exact fresh-owned B loader: same first-use view, no persistent owner retention.
def _rs_load_b_owned_ql_v1(b, Y, slot, L, k, n):
    if (not _ASTRA_QL_ON or (b.dtype) != 'float32'
            or len(b.shape) != 2 or tuple(b.shape) != (k, n)):
        return _OT_QL_PARENT_B(b, Y, slot, L, k, n)
    h = _BH_HOLD.append
    u = 1 << L
    Br = fnp.reshape(b, (2,) * L + (k // u,) + (2,) * L + (n // u,))
    quad = slot[1] if slot[1] is not None else _l3_quad(slot, 1, L)
    left_in, B1 = fnp.unstack(Br, axis=L + 1)
    b12, b22 = fnp.unstack(B1, axis=0)
    left_out = quad[(slice(None),) * (L + 1) + (0,)]
    _OT_STATS['qv_miss'] += 1  # fresh owned side was always a cache miss
    h((Br, left_in, B1, b12, b22))
    h(fnp.copyto(left_out, left_in))
    h(fnp.copyto(Y[3], b22))
    h(fnp.subtract(b22, b12, out=Y[1]))
    _ASTRA_QL_STATS['b'] += 1
    _ASTRA_QL_STATS['saved_copy_elements'] += k * n // 4
    _OT_STATS['b'] += 1

def _astra_ubown_forward_v1(b, L, k, n, side):
    # Exact body of the base B transform, with its supplied side entry.
    TB, Y1, B02, ops, basis = side
    h = _BH_HOLD.append
    _rs_load_b_owned_ql_v1(b, Y1[1], B02, L, k, n)
    for lo, hi in basis:
        h(fnp.subtract(hi, lo, out=lo))
    if ops is not None:
        for f, x, y, o in ops:
            h(f(x, y, out=o))
        return TB
    for j in range(1, L + 1):
        Y = Y1[j]
        h(fnp.add(Y[1], Y[0], out=Y[5]))
        h(fnp.subtract(Y[5], Y[2], out=Y[6]))
        h(fnp.subtract(Y[3], Y[5], out=Y[4]))
    return TB


# Exact owned-B storage/view pool. Append after v11's owned QL lifetime repair.
# Every invocation still computes the complete transform. No cache admission changes.
_OWP_MAX_BYTES = 1_412_000_000
_OWP_MAX_SLOTS = 16
_OWP = dict(active=False, ordinal=0, bytes=0, slots={}, side_index={})
_OWP_STATS = dict(hits=0, misses=0, evictions=0, fallback=0, half_hits=0, peak_bytes=0)
_OWP_PARENT_BIND = _astra_ubown_bind_v1
_OWP_PARENT_LOAD = _rs_load_b_owned_ql_v1
_OWP_PARENT_PREDICT = Estimator.predict


def _owp_evict(index):
    entry = _OWP['slots'].pop(index, None)
    if entry is not None:
        _OWP['bytes'] -= entry['bytes']
        _OWP['side_index'].pop(id(entry['side'][2]), None)
        _OWP_STATS['evictions'] += 1


def _owp_begin():
    if _OWP['active']:
        raise RuntimeError('Owned-side pool does not support nested predictions')
    _OWP['ordinal'] = 0
    _OWP['active'] = True


def _owp_end():
    # Called only after the original prediction's cache-finally chain returned.
    for index in tuple(_OWP['slots']):
        if index >= _OWP['ordinal']:
            _owp_evict(index)
    _OWP['active'] = False


def _astra_ubown_bind_v1(L, k, n, fused):
    if not _OWP['active']:
        return _OWP_PARENT_BIND(L, k, n, fused)
    index = _OWP['ordinal']
    _OWP['ordinal'] = index + 1
    key = (L, k, n, bool(fused))
    supported = (L == 6 and k > 0 and n > 0 and k % 64 == 0 and n % 64 == 0
                 and index < _OWP_MAX_SLOTS)
    size = 4 * 7 ** L * (k // (1 << L)) * (n // (1 << L)) if supported else 0
    entry = _OWP['slots'].get(index)
    if supported and size <= _OWP_MAX_BYTES and entry is not None and entry['key'] == key:
        _OWP_STATS['hits'] += 1
        return entry['side']
    _owp_evict(index)
    if not supported or size > _OWP_MAX_BYTES:
        _OWP_STATS['fallback'] += 1
        return _OWP_PARENT_BIND(L, k, n, fused)
    # Only evict old slots not yet allocated in this prediction. Used slots may
    # still back an original UBC/UBX/RC cache entry and are never overwritten.
    for stale in sorted(tuple(_OWP['slots']), reverse=True):
        if _OWP['bytes'] + size <= _OWP_MAX_BYTES:
            break
        if stale >= _OWP['ordinal']:
            _owp_evict(stale)
    if _OWP['bytes'] + size > _OWP_MAX_BYTES:
        _OWP_STATS['fallback'] += 1
        return _OWP_PARENT_BIND(L, k, n, fused)
    side = _OWP_PARENT_BIND(L, k, n, fused)
    entry = dict(key=key, side=side, bytes=size, half=None)
    _OWP['slots'][index] = entry
    _OWP['side_index'][id(side[2])] = entry
    _OWP['bytes'] += size
    _OWP_STATS['misses'] += 1
    _OWP_STATS['peak_bytes'] = max(_OWP_STATS['peak_bytes'], _OWP['bytes'])
    return side


def _rs_load_b_owned_ql_v1(b, Y, slot, L, k, n):
    entry = _OWP['side_index'].get(id(slot)) if _OWP['active'] else None
    if (entry is None or entry['side'][2] is not slot or not _ASTRA_QL_ON
            or (b.dtype) != 'float32' or tuple(b.shape) != (k, n)):
        return _OWP_PARENT_LOAD(b, Y, slot, L, k, n)
    h = _BH_HOLD.append
    u = 1 << L
    Br = fnp.reshape(b, (2,) * L + (k // u,) + (2,) * L + (n // u,))
    quad = slot[1] if slot[1] is not None else _l3_quad(slot, 1, L)
    left_in, B1 = fnp.unstack(Br, axis=L + 1)
    b12, b22 = fnp.unstack(B1, axis=0)
    left_out = entry['half']
    if left_out is None:
        left_out = entry['half'] = quad[(slice(None),) * (L + 1) + (0,)]
    else:
        _OWP_STATS['half_hits'] += 1
    _OT_STATS['qv_miss'] += 1  # preserve the original fresh-owned diagnostic
    h((Br, left_in, B1, b12, b22))
    h(fnp.copyto(left_out, left_in))
    h(fnp.copyto(Y[3], b22))
    h(fnp.subtract(b22, b12, out=Y[1]))
    _ASTRA_QL_STATS['b'] += 1
    _ASTRA_QL_STATS['saved_copy_elements'] += k * n // 4
    _OT_STATS['b'] += 1


def _owp_predict(self, *args, **kwargs):
    if (_OWP['active'] or _UBC_RUN[0] is not None or _UBX_CTX[0] is not None
            or _UBX_RC[0] is not None or _UBC_CONTEXT[0] is not None):
        return _OWP_PARENT_PREDICT(self, *args, **kwargs)
    _owp_begin()
    try:
        return _OWP_PARENT_PREDICT(self, *args, **kwargs)
    finally:
        _owp_end()


Estimator.predict = _owp_predict


# Exact terminal C-tree fusion. Preserve ordinary two-item pair tuple consumers.
class _TerminalPairs(tuple):
    def __new__(cls, pairs, first, second):
        value = tuple.__new__(cls, pairs)
        value.first = first
        value.second = second
        return value

_TERMINAL_PARENT_PAIRS = _l3o_pairs
def _l3o_pairs(slot, L):
    G = slot[0]
    pairs = _TERMINAL_PARENT_PAIRS(slot, L)
    pairs = _TerminalPairs(pairs, G[0:5:4], G[5:7])
    slot[1] = pairs
    return pairs

_TERMINAL_PARENT_LAST = _l3o_last
def _l3o_last(slot, Z, out, L, m, n):
    pairs = slot[1] if slot[1] is not None else _l3o_pairs(slot, L)
    if not isinstance(pairs, _TerminalPairs):
        return _TERMINAL_PARENT_LAST(slot, Z, out, L, m, n)
    h = _BH_HOLD.append
    owned = _RQS_OUTV.get(id(out))
    kept = owned is not None and owned[0] is out
    views = owned[1].get((L, m, n)) if kept else None
    if views is None:
        u = 1 << L
        Cr = fnp.reshape(out, (2,) * L + (m // u,) + (2,) * L + (n // u,))
        C0, C1 = fnp.unstack(Cr, axis=0)
        bl, br = fnp.unstack(C1, axis=L)
        views = (C0, bl, br, Cr, C1)
        if kept:
            owned[1][(L, m, n)] = views
        else:
            h((Cr, C0, C1, bl, br))
    elif kept:
        _RQS_STATS['outv'] += 1
    C0, bl, br = views[:3]
    p05, p23 = pairs
    # The old Z4+Z6 result lives in dead terminal Z6, preserving old Z4 for Z5.
    h(fnp.add(pairs.first, pairs.second, out=pairs.second))
    h(fnp.add(Z[5], Z[4], out=Z[5]))
    h(fnp.add(p05, p23, out=C0))
    h(fnp.add(Z[5], Z[1], out=br))
    h(fnp.subtract(br, Z[6], out=bl))
    return out


# Exact full-operand loads: trade the quarter-copy saving for fewer public calls.
# Preserves the existing load3 arithmetic and all cache/ownership lifetimes.
_ASTRA_QL_ON = False


# Exact full swapped-column copy: fewer public calls, unchanged element arithmetic.
_ASTRA_COMPUTE_ON = False




# BEGIN [opus-lazybind] BOX VIEWS v2 (2026-10-16; append LAST on GOV_v3 0640c0cf). A depth-6 A or B tree that setup never binds (its key
# is not in _PB_SINGLE) used to be bound inside predict by reshaping its arena region (billed at 7^6 r c), plus its level-1 view
# (reshape) and its quadrant view (reshape) at first load. Setup now reshapes ONE maximal tree per side, leaf (R, C) = (16, 48) for A
# and (16, 64) for B (the whole region), with its level-1 view and quadrant view; such a key's tree is that box's [..., :r, :c] slice and
# its level-1 / quadrant views are the box's views sliced the same way (free views, same elements, a strided leaf). Keys that setup
# binds keep the packed layout in every bind (v2: the keys setup ACTUALLY bound in this process, recorded during setup, so a key in
# _PB_SINGLE that the setup wall left unbound is boxed too); each key keeps one layout for the whole process (shape-keyed caches). The C side and the
# u/v leg B trees (256 / 384 rows, which the UBC/UBX caches copy) stay as they were.
_LB_ON = True
_LB_SPEC = {0: (16, 48), 1: (16, 64)}                       # kind -> box leaf (R, C) at depth 6
_LB_SETUP_KEYS = set()                                      # keys _ipt_side bound during setup (packed for good)
_LB_SETUP = [False]
_LB_BOX = {}                                                # kind -> dict(arena, start, R, C, T, V1, quad)
_LB_OF = {}                                                 # id(view) -> (view, kind, r, c) for views cut from a box
_LB_OF_CAP = 4096
_LB_STATS = dict(boxes=0, tree=0, level1=0, quad=0)
_LB_PARENT_VIEW = _ipt_view
_LB_PARENT_LV1 = _lvf_rs_level1
_LB_PARENT_QUAD = _l3_quad
_LB_PARENT_PB = _pb_bind
_PB_CACHES = tuple(_PB_CACHES) + ('_LB_BOX', '_LB_OF')


def _lb_note(view, kind, r, c):
    if len(_LB_OF) >= _LB_OF_CAP:
        _LB_OF.pop(next(iter(_LB_OF)))
    _LB_OF[id(view)] = (view, kind, r, c)


def _lb_make_boxes():
    if not _LB_ON or _SCRATCH is None or _LB_BOX:
        return
    arena = _SCRATCH[0]
    L = 6
    region = _IPT_REGION[L]
    nr = L - 1
    for kind, (R, C) in _LB_SPEC.items():
        if 7 ** L * R * C > region[kind]:
            continue
        start = (0, region[0])[kind]
        T = _LB_PARENT_VIEW(arena, start, (7,) * L + (R, C))
        data = slice(0, 7, 2) if kind == 0 else slice(0, 4)
        V1 = fnp.reshape(T[(data,) * nr], (2, 2) * nr + (7, R, C))
        base = list(range(2 * nr)) + list(range(2 * nr, 2 * nr + 3))
        G = fnp.transpose(V1, [base[x] for x in _rs_nat_perm(L, 0)])
        D = G[0:7:2] if kind == 0 else G[0:4]
        Q = fnp.reshape(D, (2, 2) + tuple(int(x) for x in G.shape[1:]))
        quad = fnp.transpose(Q, [0] + list(range(2, L + 2)) + [1] + list(range(L + 2, 2 * L + 2)))
        _LB_BOX[kind] = dict(arena=arena, start=start, R=R, C=C, T=T, V1=V1, quad=quad, keep=(G, D, Q))
        _LB_STATS['boxes'] += 1


def _pb_bind(t0):
    _LB_SETUP[0] = True
    try:
        _LB_PARENT_PB(t0)
    finally:
        _LB_SETUP[0] = False
    _lb_make_boxes()


_LB_PARENT_SIDE = _ipt_side
_LB_IN_SIDE = [None]


def _ipt_side(kind, L, rows, cols):
    # marks the key being bound, so only its own tree view (and no other caller of _ipt_view) can come from a box
    if _LB_SETUP[0]:
        _LB_SETUP_KEYS.add((kind, L, rows, cols))
    saved = _LB_IN_SIDE[0]
    _LB_IN_SIDE[0] = (kind, L, rows, cols)
    try:
        return _LB_PARENT_SIDE(kind, L, rows, cols)
    finally:
        _LB_IN_SIDE[0] = saved


def _ipt_view(arena, start, shape):
    if (_LB_ON and _LB_BOX and _SCRATCH is not None and arena is _SCRATCH[0] and len(shape) == 8
            and tuple(shape[:6]) == (7,) * 6):
        region = _IPT_REGION[6]
        kind = 0 if start == 0 else 1 if start == region[0] else None
        box = _LB_BOX.get(kind) if kind is not None else None
        r, c = int(shape[6]), int(shape[7])
        if (box is not None and box['arena'] is arena and box['start'] == start and r <= box['R'] and c <= box['C']
                and _LB_IN_SIDE[0] == (kind, 6, 64 * r, 64 * c)
                and not _LB_SETUP[0] and (kind, 6, 64 * r, 64 * c) not in _LB_SETUP_KEYS
                and not (kind == 1 and 64 * r in (256, 384))):
            view = box['T'][..., :r, :c]
            _BH_HOLD.append(view)
            _lb_note(view, kind, r, c)
            _LB_STATS['tree'] += 1
            return view
    return _LB_PARENT_VIEW(arena, start, shape)


def _lvf_rs_level1(kind, L, T, tail):
    got = _LB_OF.get(id(T))
    if got is None or got[0] is not T or L != 6 or len(tail) != 2 or got[1] != kind:
        return _LB_PARENT_LV1(kind, L, T, tail)
    _view, _kind, r, c = got
    if (r, c) != (int(tail[0]), int(tail[1])):
        return _LB_PARENT_LV1(kind, L, T, tail)
    V1 = _LB_BOX[kind]['V1'][..., :r, :c]
    nr = L - 1
    swap = list(range(2 * nr))
    base = swap + list(range(2 * nr, 2 * nr + 1 + len(tail)))
    Vn = fnp.transpose(V1, [base[x] for x in _rs_nat_perm(L, 0)])
    groups = [Vn]
    _lb_note(Vn, kind, r, c)
    _LB_STATS['level1'] += 1
    return [(fnp.unstack(G, axis=0), [G, None]) for G in groups], groups


def _l3_quad(slot, kind, L):
    G = slot[0]
    got = _LB_OF.get(id(G)) if G is not None else None
    if got is None or got[0] is not G or L != 6 or got[1] != kind or kind not in _LB_BOX:
        return _LB_PARENT_QUAD(slot, kind, L)
    _view, _kind, r, c = got
    f = slice(None)
    quad = _LB_BOX[kind]['quad'][(f,) * L + (slice(0, r),) + (f,) * L + (slice(0, c),)]
    _BH_HOLD.append(G)
    slot[0] = None; slot[1] = quad
    _L3_STATS['quads'] += 1
    _LB_STATS['quad'] += 1
    return quad
# END [opus-lazybind] BOX VIEWS v2


# Exact terminal Smirnov scale batching. Only output-only scale nodes move.
# All add/subtract intermediates retain their operation, order and destination.
_TPS_META = {}
for _tps_record in _SMX_RECORDS.values():
    _tps_plan = _tps_record['prepared']['P']
    if id(_tps_plan) in _TPS_META:
        continue
    _tps_inputs, _tps_groups, _tps_outputs, _tps_uses = _tps_plan
    _tps_scales = {ref: (args[0], head[2])
        for head, nodes in _tps_groups if head[1] == 'scale'
        for ref, args in nodes if _tps_uses.get(ref, 0) == 0}
    assert set(_tps_scales) == set(_tps_outputs)
    assert all(head[1] != 'scale' or all(ref in _tps_scales for ref, args in nodes)
               for head, nodes in _tps_groups)
    _tps_coefficients = tuple(float(_tps_scales[ref][1]) for ref in _tps_outputs)
    _TPS_META[id(_tps_plan)] = (_tps_plan, _tps_scales, _tps_coefficients)
del _tps_record, _tps_plan, _tps_inputs, _tps_groups, _tps_outputs, _tps_uses
del _tps_scales, _tps_coefficients
assert all(id(record['prepared']['P']) in _TPS_META for record in _ASTRA_SM40_RECORDS.values())
_TPS_COEFFICIENTS = {}
def _tps_bind_coefficients():
    _TPS_COEFFICIENTS.clear()
    for key, (plan, scales, coefficients) in _TPS_META.items():
        _TPS_COEFFICIENTS[key] = fnp.asarray([[[v]] for v in coefficients], dtype=fnp.float32)
_TPS_PARENT_BIND = _pb_bind
def _pb_bind(t0):
    _TPS_PARENT_BIND(t0)
    _tps_bind_coefficients()

_TPS_PARENT_GROUPED = _astra_sm40_linear_grouped
def _astra_sm40_linear_grouped(fnp, plan, inputs, shape, stats, out=None, prepared=None):
    meta = _TPS_META.get(id(plan))
    if (meta is None or meta[0] is not plan or id(plan) not in _TPS_COEFFICIENTS
            or out is not None or not isinstance(prepared, _Sm40Prepared)):
        return _TPS_PARENT_GROUPED(fnp, plan, inputs, shape, stats, out=out, prepared=prepared)
    key = ('terminal_scale_v1', id(plan), id(inputs))
    program = prepared.programs.get(key)
    if program is None:
        input_refs, groups, output_refs, uses = plan
        batches, node_views = prepared
        values = {ref: inputs[i] for ref, i in input_refs.items()}
        ops = []; node_at = 0; peak = 0; scalar_bytes = _rc_math.prod(shape) * 4
        operations = {'add': fnp.add, 'sub': fnp.subtract}
        for group_index, ((depth, op, lit), nodes) in enumerate(groups):
            if op != 'scale':
                left = [values[args[0]] for ref, args in nodes]
                right = [values[args[1]] for ref, args in nodes]
                if len(nodes) == 1:
                    lhs, rhs, destination = left[0], right[0], node_views[node_at]
                else:
                    lhs, rhs, destination = left, right, batches[group_index]
                ops.append((operations[op], lhs, rhs, destination))
                for index, (ref, args) in enumerate(nodes):
                    values[ref] = node_views[node_at + index]
            node_at += len(nodes)
            peak = max(peak, 2 * len(nodes) * scalar_bytes)
        outputs = tuple(values[meta[1][ref][0]] for ref in output_refs)
        program = (inputs, tuple(ops), outputs, peak)
        if len(prepared.programs) >= 16:
            prepared.programs.clear()
        prepared.programs[key] = program
    _, ops, outputs, peak = program
    held = []
    for operation, lhs, rhs, destination in ops:
        held.append(operation(lhs, rhs, out=destination))
    answer = fnp.multiply(outputs, _TPS_COEFFICIENTS[id(plan)])
    stats['temp_peak'] = max(stats['temp_peak'], peak)
    stats['temp_live'] = 0
    return answer


# Exact ORIGINAL main-read padding views, prepared as two unions on existing owners.
# Requires _peel_padding_rectangles and an already bound _ASTRA_SM40_ENV.
# Cache formats and lifecycle are unchanged; _astra_sm40_clear retires all views.
_MR_PADDING_KEYS_V1 = ((576, 5056, 704, 384, 192, 912, 240, 3, 6, 3), (576, 5120, 704, 384, 192, 928, 240, 3, 6, 3), (576, 5184, 704, 384, 192, 928, 240, 3, 6, 3), (576, 5184, 736, 384, 192, 928, 256, 3, 6, 3), (576, 6144, 736, 384, 192, 1088, 256, 3, 6, 3), (576, 8832, 736, 384, 192, 1536, 256, 3, 6, 3), (640, 7232, 768, 384, 224, 1280, 256, 3, 6, 3), (640, 7360, 768, 384, 224, 1312, 256, 3, 6, 3), (640, 7552, 736, 384, 224, 1344, 256, 3, 6, 3), (672, 5888, 736, 384, 224, 1056, 256, 3, 6, 3), (672, 6208, 768, 384, 224, 1120, 256, 3, 6, 3), (672, 6272, 768, 384, 224, 1120, 256, 3, 6, 3), (672, 8704, 768, 384, 224, 1536, 256, 3, 6, 3), (672, 10112, 736, 384, 224, 1760, 256, 3, 6, 3), (672, 10112, 768, 384, 224, 1760, 256, 3, 6, 3), (672, 10176, 736, 384, 224, 1760, 256, 3, 6, 3), (704, 10304, 768, 384, 256, 1792, 256, 3, 6, 3), (736, 8832, 768, 384, 256, 1536, 256, 3, 6, 3), (768, 7104, 800, 384, 256, 1248, 288, 3, 6, 3), (768, 7168, 800, 384, 256, 1280, 288, 3, 6, 3), (768, 8640, 800, 384, 256, 1504, 288, 3, 6, 3), (768, 8768, 768, 384, 256, 1536, 256, 3, 6, 3), (768, 8896, 800, 384, 256, 1568, 288, 3, 6, 3), (768, 9024, 800, 384, 256, 1568, 288, 3, 6, 3), (832, 11648, 832, 0, 288, 1952, 288, 3, 6, 3), (832, 11712, 832, 0, 288, 1952, 288, 3, 6, 3), (832, 11776, 832, 0, 288, 1984, 288, 3, 6, 3), (864, 9920, 832, 0, 288, 1664, 288, 3, 6, 3), (864, 9920, 864, 0, 288, 1664, 288, 3, 6, 3), (864, 9984, 832, 0, 288, 1664, 288, 3, 6, 3), (864, 9984, 864, 0, 288, 1664, 288, 3, 6, 3), (864, 11776, 832, 0, 288, 1984, 288, 3, 6, 3), (864, 11840, 832, 0, 288, 1984, 288, 3, 6, 3), (896, 9920, 864, 0, 320, 1664, 288, 3, 6, 3), (896, 9984, 864, 0, 320, 1664, 288, 3, 6, 3), (896, 10048, 864, 0, 320, 1696, 288, 3, 6, 3), (928, 8064, 864, 0, 320, 1344, 288, 3, 6, 3), (928, 8064, 896, 0, 320, 1344, 320, 3, 6, 3), (928, 8128, 864, 0, 320, 1376, 288, 3, 6, 3), (960, 6144, 928, 0, 320, 1024, 320, 3, 6, 3), (992, 6144, 960, 0, 352, 1024, 320, 3, 6, 3))

def _mr_prebind_padding_v1(module, keys=None):
    if keys is None:
        keys = _MR_PADDING_KEYS_V1
    keys = tuple(sorted(set(tuple(map(int, key)) for key in keys)))
    fulla, fullb = module._sm40_padding
    ashape, bshape = tuple(map(int, fulla.shape)), tuple(map(int, fullb.shape))
    grids, entries = {}, {}
    rectangles = (set(), set())
    for key in keys:
        m,k,n,rank,cm,ck,cn,ar,ak,an = key
        ma,kk,nb = ar*cm,ak*ck,an*cn
        if not (0 < m <= ma <= ashape[0] and 0 < k and 0 <= rank and
                k+rank <= kk <= ashape[1] and kk <= bshape[0] and
                0 < n <= nb <= bshape[1]):
            raise ValueError('main-read padding exceeds existing owner')
        gridkey = (cm,ck,cn,ar,ak,an)
        if gridkey not in module._sm40_padding_grid and gridkey not in grids:
            ra,rb = (0,ma,0,kk),(0,kk,0,nb)
            av = tuple((i*cm,(i+1)*cm,j*ck,(j+1)*ck) for i in range(ar) for j in range(ak))
            bv = tuple((i*ck,(i+1)*ck,j*cn,(j+1)*cn) for i in range(ak) for j in range(an))
            grids[gridkey] = (ra,rb,av,bv)
            rectangles[0].update((ra,)+av)
            rectangles[1].update((rb,)+bv)
        if key not in module._sm40_padding_cache:
            ya,yb = (0,m,0,k),(0,k,0,n)
            oa = (0,m,k,k+rank) if rank else None
            ob = (k,k+rank,0,n) if rank else None
            zero = []
            if m < ma:
                zero.append((0,(m,ma,0,kk)))
            if k+rank < kk:
                zero.append((0,(0,m,k+rank,kk)))
                zero.append((1,(k+rank,kk,0,nb)))
            if n < nb:
                zero.append((1,(0,k+rank,n,nb)))
            entries[key] = (ya,yb,oa,ob,tuple(zero))
            rectangles[0].add(ya)
            rectangles[1].add(yb)
            if rank:
                rectangles[0].add(oa)
                rectangles[1].add(ob)
            for side, rect in zero:
                rectangles[side].add(rect)
    views = tuple(_peel_padding_rectangles(owner, rects) if rects else {} for owner,rects in zip((fulla,fullb),rectangles))
    a,b = views
    for key,(ra,rb,av,bv) in grids.items():
        module._sm40_padding_grid[key] = (a[ra],b[rb],tuple(a[r] for r in av),tuple(b[r] for r in bv))
    for key,(ya,yb,oa,ob,zero) in entries.items():
        module._sm40_padding_cache[key] = (a[ya],b[yb],a[oa] if oa is not None else None,b[ob] if ob is not None else None,tuple(views[side][r] for side,r in zero))
    return (len(grids),len(entries),len(rectangles[0]),len(rectangles[1]))


# Setup-only union of original main-read side prefixes. No numeric owners.
# Requires existing _peel_split_ranges and fixed _MR_GEOMETRY_V1.
def _mr_prefix_schedule_v1(points, capacity):
    points = tuple(sorted(set(points)))
    memo = {}
    def solve(ps, axes):
        key = (ps, axes)
        if key in memo:
            return memo[key]
        if not axes:
            value = (0, None)
        else:
            choices = []
            for axis in axes:
                values = tuple(sorted(set(p[axis] for p in ps)))
                rest = tuple(a for a in axes if a != axis)
                children = tuple((v, solve(tuple(p for p in ps if p[axis] == v), rest)) for v in values)
                cost = int(any(v != capacity[axis] for v in values)) + sum(child[0] for _,child in children)
                choices.append((cost, axis, children))
            cost,axis,children = min(choices,key=lambda v:(v[0],v[1]))
            value = (cost,(axis,tuple((v,child[1]) for v,child in children)))
        memo[key] = value
        return value
    return solve(points,(0,1,2))

def _mr_prefix_apply_v1(owner, axes, schedule):
    result = {}
    def visit(value, node, prefix):
        if node is None:
            result[tuple(prefix)] = value
            return
        axis,children = node
        parts = _peel_split_ranges(value,tuple((0,n) for n,_ in children),axes[axis])
        for n,child in children:
            prefix[axis] = n
            visit(parts[(0,n)],child,prefix)
    visit(owner,schedule,[None,None,None])
    return result

def _mr_bind_side_prefix_group_v1(ker, kind, frame, requests):
    M=ker.M; fnp=ker.fnp; L=frame['L']; u=1<<L; family=ker.family[0]
    requests=tuple(sorted(set(tuple(map(int,x)) for x in requests)))
    requests=tuple(x for x in requests if (family,kind,L)+x not in M._sm40_cache)
    if not requests:
        return (0,0,0)
    points=tuple((P,rows//u,cols//u) for P,rows,cols in requests)
    capacity=(frame['P'],frame['rows'],frame['cols'])
    assert all(rows%u==0 and cols%u==0 for P,rows,cols in requests)
    assert all(all(0<x<=y for x,y in zip(point,capacity)) for point in points)
    calls,schedule=_mr_prefix_schedule_v1(points,capacity)
    original=sum(point!=capacity for point in points)
    if calls>=original:
        return (0,0,0)
    tail=(-3,-2,-1)
    ts=_mr_prefix_apply_v1(frame['T'],tail,schedule)
    gs=_mr_prefix_apply_v1(frame['G'],(1,L+1,2*L+1),schedule)
    ls={j:(_mr_prefix_apply_v1(frame['levels'][j],tail,schedule) if j<L else ts) for j in range(2,L+1)}
    bs=tuple((_mr_prefix_apply_v1(lo,tail,schedule),_mr_prefix_apply_v1(hi,tail,schedule)) for lo,hi in frame['basis'])
    for request,point in zip(requests,points):
        P,rows,cols=request
        T,G=ts[point],gs[point]
        chunks=[None,fnp.unstack(G,axis=0)]
        levels=[None,None]
        for j in range(2,L+1):
            level=ls[j][point]
            levels.append(level)
            chunks.append(fnp.unstack(level,axis=0))
        basis=[(lo[point],hi[point]) for lo,hi in bs]
        ops=[]
        if kind==0:
            for j in range(1,L+1):
                X=chunks[j];V=G if j==1 else levels[j]
                ops.extend(((fnp.subtract,X[4],X[0],X[5]),(fnp.subtract,V[2:7:4],X[5],V[3:0:-2])))
        else:
            for j in range(1,L+1):
                Y=chunks[j];V=G if j==1 else levels[j]
                ops.extend(((fnp.add,Y[1],Y[0],Y[5]),(fnp.subtract,V[5:2:-2],V[2:6:3],V[6:3:-2])))
        M._sm40_cache[(family,kind,L,P,rows,cols)]=(T,chunks,G,basis,ops)
    return (len(points),original*(3*L-2),calls*(3*L-2))

def _mr_prebind_sides_v1(shapes=None):
    if shapes is None:
        shapes=_MR_GEOMETRY_V1
    env=_ASTRA_SM40_ENV
    groups={}
    for shape in shapes:
        m,k,n,rank=shape
        plan=_ASTRA_SM40_PLANS.get(tuple(shape))
        if plan is None:
            continue
        name,L,_=plan;ker=_ASTRA_SM40_KERNELS[name];ar,ak,an=ker.record['shape'];u=1<<L
        cm=_rc_math.ceil(m/ar/u)*u;ck=_rc_math.ceil((k+rank)/ak/u)*u;cn=_rc_math.ceil(n/an/u)*u
        family=_astra_sm40_family_for(L,cm,ck,cn);nominal=family[2]
        for P in set(min(nominal,40-i) for i in range(0,40,nominal)):
            for kind,rows,cols in ((0,cm,ck),(1,ck,cn)):
                key=(family[0],kind,L,P,rows,cols)
                if key in env._sm40_cache:
                    continue
                compact=cols//u if kind==1 and (family[0],cols//u) in _OPUS_CB_LAZY else None
                group=(name,family,kind,compact)
                groups.setdefault(group,set()).add((P,rows,cols))
    if any(group[3] is not None for group in groups) and not env._sm40_compact_b:
        for name,width in _OPUS_CB_ORDER:
            family=next(f for f in _ASTRA_SM40_FAMILIES if f[0]==name)
            env._sm40_compact_b[name,width]=_astra_sm40_bind_compact_b(env.fnp,env,env._sm40_owner,family,width)
        _OPUS_CB_STATS['lazy_bind_events']+=1
    result=[]
    for (name,family,kind,compact),requests in groups.items():
        ker=_ASTRA_SM40_KERNELS[name];ker.family=family
        frame=env._sm40_frames[family[0]]['sides'][kind]
        if compact is not None:
            frame=env._sm40_compact_b[family[0],compact]
        value=_mr_bind_side_prefix_group_v1(ker,kind,frame,requests)
        if value[0]:
            result.append((family[0],kind,compact,value))
    return tuple(result)


# Static original-mainread topology. Uses only existing frames/numeric owners.
def _mr_prepare_shape(shape, padding=True, groups=True):
    m,k,n,rank=shape
    plan=_ASTRA_SM40_PLANS.get(shape)
    if plan is None:return None
    name,L,_=plan
    env=_ASTRA_SM40_ENV;ker=_ASTRA_SM40_KERNELS[name]
    ar,ak,an=ker.record['shape'];u=1<<L
    cm=_rc_math.ceil(m/ar/u)*u
    ck=_rc_math.ceil((k+rank)/ak/u)*u
    cn=_rc_math.ceil(n/an/u)*u
    ker.family=_astra_sm40_family_for(L,cm,ck,cn);P=ker.family[2]
    if padding:_astra_sm40_padding_views(env,m,k,n,rank,cm,ck,cn,ar,ak,an)
    key=(L,cm,ck,cn,P)
    if key not in env._sm40_outer_cache:
        LA=env._sm40_outer['A'][:,:cm,:ck]
        RB=env._sm40_outer['B'][:,:ck,:cn]
        PC=env._sm40_outer['C'][:,:cm,:cn]
        pc=tuple(fnp.unstack(PC,axis=0));cuts=list(range(P,40,P))
        parts=tuple(zip(fnp.split(LA,cuts,axis=0),fnp.split(RB,cuts,axis=0),fnp.split(PC,cuts,axis=0)))
        env._sm40_outer_cache[key]=(LA,RB,PC,pc,parts)
    if groups:
        ker.group_views('L',(cm,ck));ker.group_views('R',(ck,cn));ker.group_views('P',(cm,cn))
    if any((key,i)not in env._sm40_io_cache for i in range(len(env._sm40_outer_cache[key][-1]))):
        _mainread_bind_batch_io(ker,key)
    return (name,)+key

# Fixed geometry roster from 16 broad saved networks; no prediction-dependent selection.
_MR_GEOMETRY_V1 = ((864, 9920, 832, 0), (960, 6144, 928, 0), (832, 11648, 832, 0), (928, 8064, 896, 0), (832, 11776, 832, 0), (896, 9920, 864, 0), (672, 10112, 736, 384), (928, 8064, 864, 0), (576, 5120, 704, 384), (736, 8832, 768, 384), (576, 5056, 704, 384), (672, 6208, 768, 384), (768, 7168, 800, 384), (768, 8896, 800, 384), (928, 8128, 864, 0), (896, 10048, 864, 0), (992, 6144, 960, 0), (704, 10304, 768, 384), (576, 5184, 736, 384), (576, 6144, 736, 384), (672, 5888, 736, 384), (640, 7232, 768, 384), (640, 7360, 768, 384), (640, 7552, 736, 384), (672, 8704, 768, 384), (768, 7104, 800, 384), (768, 8640, 800, 384), (576, 8832, 736, 384))

# Fixed once-per-arena preparation is paid inside the first successful prediction.
# It only builds views/program metadata; the published prediction is never written.
_MR_POST_OWNER = [None]
_MR_POST_STATS = dict(runs=0, generic_bound=0, generic_finished=0)
_MR_POST_PARENT_RESET = _pb_reset
def _pb_reset(saved):
    try:return _MR_POST_PARENT_RESET(saved)
    finally:_MR_POST_OWNER[0]=None

def _mr_post_first_v1():
    if _SCRATCH is None or not _ASTRA_SM40_ON:
        return
    arena=_SCRATCH[0]
    if _MR_POST_OWNER[0] is arena or _ASTRA_SM40_ENV._sm40_owner is not arena:
        return
    _TR_LAST[0]=None
    try:
        _mr_prebind_padding_v1(_ASTRA_SM40_ENV)
        _mr_prebind_sides_v1()
        for shape in _MR_GEOMETRY_V1:
            _mr_prepare_shape(shape,False,False)
        bound=finished=0
        for kind,L,rows,cols in _PB_SINGLE[:0]:
            cache=(_IPT_A,_IPT_B,_IPT_C)[kind]
            bound += (L,rows,cols) not in cache
            entry=_ipt_side(kind,L,rows,cols)
            slot=entry[2]
            if type(slot)is list and slot[1] is None:
                if kind==2:_l3o_pairs(slot,L)
                else:_l3_quad(slot,kind,L)
                finished+=1
        for kind,L,rows,cols in reversed(_PB_SINGLE[:0]):
            (_IPT_A,_IPT_B,_IPT_C)[kind].touch((L,rows,cols))
        _MR_POST_STATS.update(runs=_MR_POST_STATS['runs']+1,generic_bound=bound,generic_finished=finished)
        _MR_POST_OWNER[0]=arena
    finally:
        _TR_LAST[0]=None
        _BH_HOLD.clear()
_MR_POST_PARENT_PREDICT=Estimator.predict
def _mr_post_predict_v1(self,*args,**kwargs):
    result=_MR_POST_PARENT_PREDICT(self,*args,**kwargs)
    _mr_post_first_v1()
    return result
Estimator.predict=_mr_post_predict_v1


# Fixed generic prefix charged views, explicitly prepared and charged in setup.
# Existing tree layouts, owners, LB2 classifications, and arithmetic are preserved.
_GCV_OWNER = [None]
_GCV_TREES = {}
_GCV_LEVEL1 = {}
_GCV_QUADS = {}
_GCV_PARENT_VIEW = _ipt_view
_GCV_PARENT_LEVEL1 = _lvf_rs_level1
_GCV_PARENT_QUAD = _l3_quad
_GCV_PARENT_RESET = _pb_reset
_GCV_PARENT_BIND = _pb_bind
_GCV_STATS = dict(trees=0,level1=0,quads=0,tree_hits=0,level1_hits=0,quad_hits=0)

def _gcv_clear():
    _GCV_OWNER[0]=None
    _GCV_TREES.clear();_GCV_LEVEL1.clear();_GCV_QUADS.clear()
    for key in _GCV_STATS:_GCV_STATS[key]=0

def _gcv_quad_prepare(G,kind,L):
    key=(id(G),kind,L)
    if key not in _GCV_QUADS:
        data=G[0:7:2] if kind==0 else G[0:4]
        Q=fnp.reshape(data,(2,2)+tuple(int(x) for x in G.shape[1:]))
        _GCV_QUADS[key]=(G,Q)
        _GCV_STATS['quads']+=1

def _gcv_prepare(prefix=280):
    if _SCRATCH is None:return
    arena=_SCRATCH[0]
    if _GCV_OWNER[0] is not arena:
        _gcv_clear();_GCV_OWNER[0]=arena
    for kind,L,rows,cols in _PB_SINGLE[:prefix]:
        cache=(_IPT_A,_IPT_B,_IPT_C)[kind]
        entry=dict.get(cache,(L,rows,cols))
        if entry is not None:
            slot=entry[2]
            if kind<2 and type(slot)is list and slot[1]is None and slot[0]is not None:
                got=_LB_OF.get(id(slot[0]))
                if got is None or got[0]is not slot[0]:
                    _gcv_quad_prepare(slot[0],kind,L)
            continue
        # Boxed lazy sides already use setup-charged shared views, so leave them alone.
        u=1<<L;r,c=rows//u,cols//u;box=_LB_BOX.get(kind)
        if (L==6 and box is not None and box['arena']is arena and r<=box['R'] and c<=box['C']
            and (kind,L,rows,cols)not in _LB_SETUP_KEYS and not(kind==1 and rows in(256,384))):
            continue
        region=_IPT_REGION[L];start=(0,region[0],region[0]+region[1])[kind]
        shape=(7,)*L+(r,c);key=(start,shape)
        got=_GCV_TREES.get(key)
        if got is None:
            T=_LB_PARENT_VIEW(arena,start,shape)
            _GCV_TREES[key]=(arena,T);_GCV_STATS['trees']+=1
        else:T=got[1]
        lvkey=(id(T),kind,L,(r,c))
        got=_GCV_LEVEL1.get(lvkey)
        if got is None:
            nr=L-1;data=slice(0,7,2)if kind==0 else slice(0,4)
            R=T[(data,)*nr]
            V1=fnp.reshape(R,(2,2)*nr+(7,r,c))
            swap=[x for p in range(nr)for x in(2*p+1,2*p)]if kind==2 else list(range(2*nr))
            base=swap+list(range(2*nr,2*nr+3))
            G=fnp.transpose(V1,[base[x]for x in _rs_nat_perm(L,0)])
            _GCV_LEVEL1[lvkey]=(T,G);_GCV_STATS['level1']+=1
        else:G=got[1]
        if kind<2:_gcv_quad_prepare(G,kind,L)

def _ipt_view(arena,start,shape):
    if _GCV_OWNER[0]is arena:
        got=_GCV_TREES.get((start,tuple(shape)))
        if got is not None and got[0]is arena:
            _GCV_STATS['tree_hits']+=1
            _BH_HOLD.append(got[1])
            return got[1]
    return _GCV_PARENT_VIEW(arena,start,shape)

def _lvf_rs_level1(kind,L,T,tail):
    got=_GCV_LEVEL1.get((id(T),kind,L,tuple(tail)))
    if got is not None and got[0]is T and _SCRATCH is not None and _GCV_OWNER[0]is _SCRATCH[0]:
        G=got[1];_GCV_STATS['level1_hits']+=1
        return [(fnp.unstack(G,axis=0),[G,None])],[G]
    return _GCV_PARENT_LEVEL1(kind,L,T,tail)

def _l3_quad(slot,kind,L):
    G=slot[0];got=_GCV_QUADS.get((id(G),kind,L))if G is not None else None
    if got is not None and got[0]is G and _SCRATCH is not None and _GCV_OWNER[0]is _SCRATCH[0]:
        Q=got[1]
        quad=fnp.transpose(Q,[0]+list(range(2,L+2))+[1]+list(range(L+2,2*L+2)))
        _BH_HOLD.append((G,Q));slot[0]=None;slot[1]=quad
        _L3_STATS['quads']+=1;_GCV_STATS['quad_hits']+=1
        return quad
    return _GCV_PARENT_QUAD(slot,kind,L)

def _pb_bind(t0):
    _GCV_PARENT_BIND(t0)
    _gcv_prepare(280)
    _PB_LOG.append(('generic_charged_views',len(_GCV_TREES),len(_GCV_QUADS),round(_pb_time.monotonic()-t0,3)))

def _pb_reset(saved):
    try:return _GCV_PARENT_RESET(saved)
    finally:_gcv_clear()


