class _SetupAliasHold:
    def __init__(self, namespace):
        self.namespace = namespace
        self.held = []
        self.calls = 0
        for name in ('reshape', 'transpose', 'moveaxis', 'swapaxes', 'unstack', 'split', 'squeeze', 'expand_dims', 'broadcast_to'):
            setattr(self, name, self.wrap(getattr(namespace, name)))

    def wrap(self, operation):
        def view(*args, **kwargs):
            result = operation(*args, **kwargs)
            self.held.append((args, kwargs, result))
            self.calls += 1
            return result
        return view

    def __getattr__(self, name):
        value = getattr(self.namespace, name)
        setattr(self, name, value)
        return value

