# Break only candidate-owned closure cycles; public calls/order unchanged.
def _mr_prefix_schedule_v1(points, capacity):
    points = tuple(sorted(set(points)))
    memo = {}
    def solve(ps, axes):
        key = (ps, axes)
        if key in memo:
            return memo[key]
        if not axes:
            value = (0, None)
        else:
            choices = []
            for axis in axes:
                values = tuple(sorted(set(p[axis] for p in ps)))
                rest = tuple(a for a in axes if a != axis)
                children = tuple((v, solve(tuple(p for p in ps if p[axis] == v), rest)) for v in values)
                cost = int(any(v != capacity[axis] for v in values)) + sum(child[0] for _,child in children)
                choices.append((cost, axis, children))
            cost,axis,children = min(choices,key=lambda v:(v[0],v[1]))
            value = (cost,(axis,tuple((v,child[1]) for v,child in children)))
        memo[key] = value
        return value
    try:
        return solve(points,(0,1,2))
    finally:
        solve = None

def _mr_prefix_apply_v1(owner, axes, schedule):
    result = {}
    def visit(value, node, prefix):
        if node is None:
            result[tuple(prefix)] = value
            return
        axis,children = node
        parts = _peel_split_ranges(value,tuple((0,n) for n,_ in children),axes[axis])
        for n,child in children:
            prefix[axis] = n
            visit(parts[(0,n)],child,prefix)
    try:
        visit(owner,schedule,[None,None,None])
        return result
    finally:
        visit = None

class _SetupAliasHold:
    def __init__(self, namespace):
        self.namespace = namespace
        self.held = []
