# End-only retained storage cap. Live admission and transform arithmetic stay unchanged.
_O18_OWP_RETAIN_BYTES = 950_000_000
_O18_OWP_RETAIN_PARENT_END = _owp_end
_O18_OWP_RETAIN_STATS = dict(calls=0, trimmed_slots=0, trimmed_bytes=0, skipped_context=0)

def _owp_end():
    # _owp_predict invokes this only after its parent prediction and all inner
    # UBC/UBX/RC/RQX finally blocks have returned. Preserve original cleanup first.
    _O18_OWP_RETAIN_PARENT_END()
    _O18_OWP_RETAIN_STATS['calls'] += 1
    # Defensive no-op on an unexpected live consumer; never evict live storage.
    if (_OWP['active'] or _UBC_RUN[0] is not None or _UBC_CONTEXT[0] is not None
            or _UBX_CTX[0] is not None or _UBX_RC[0] is not None):
        _O18_OWP_RETAIN_STATS['skipped_context'] += 1
        return
    before = _OWP['bytes']
    for index in sorted(tuple(_OWP['slots']), reverse=True):
        if _OWP['bytes'] <= _O18_OWP_RETAIN_BYTES:
            break
        _owp_evict(index)
        _O18_OWP_RETAIN_STATS['trimmed_slots'] += 1
    _O18_OWP_RETAIN_STATS['trimmed_bytes'] += before - _OWP['bytes']

# October18: share existing capacities for the five optional shared routes.
# Same operands, actual body, orientation, L/P, eligibility and call debit.
_O18_SHARED_FAMILY_MAP = {'o18shared_L5P40_4_10_32': 'sm12_e0_L5P40', 'o18shared_L5P40_4_9_29': 'o18union_L5P40_9_9_41', 'o18shared_L5P40_8_32_4': 'sm12_e1_L5P40', 'o18shared_L5P40_8_4_32': 'o18union_L5P40_9_9_41', 'o18shared_L5P40_9_4_32': 'o18union_L5P40_9_9_41'}
_O18_SHARED_ORIGINAL_PLANS = dict(_O18_SHARED_PLANS)
_O18_SHARED_ORIGINAL_FAMILIES = tuple(_O18_SHARED_FAMILIES)
def _o18_shared_capacity_plan(plan):
    old = _SMX_FAMILIES[plan[1]]
    target = _O18_SHARED_FAMILY_MAP.get(plan[1], plan[1])
    new = _SMX_FAMILIES[target]
    assert old[1:3] == new[1:3]
    assert all(a <= b for a, b in zip(old[3:], new[3:]))
    return (plan[0], target) + tuple(plan[2:])
_O18_SHARED_PLANS = {shape: _o18_shared_capacity_plan(plan)
                     for shape, plan in _O18_SHARED_PLANS.items()}
_O18_SHARED_RULES = {shape: (gain, cost, _o18_shared_capacity_plan(plan))
                     for shape, (gain, cost, plan) in _O18_SHARED_RULES.items()}
for _o18_shared_shape, _o18_shared_plan in _O18_SHARED_PLANS.items():
    assert _o18_shared_shape not in _SM12_RULE
    _SM12_PLANS[_o18_shared_shape] = _o18_shared_plan
# Preserve the registry entries for defensive historical fallbacks. The
# existing _rf192_bind live set now omits all five inactive frames, so none
# is constructed in setup. No global family or original SM12 plan changes.
_O18_SHARED_FAMILIES = tuple(_SMX_FAMILIES[name]
                           for name in sorted(set(_O18_SHARED_FAMILY_MAP.values())))
assert not (set(_O18_SHARED_FAMILY_MAP) &
            {plan[1] for table in (_SM12_PLANS, _O18_UNION_BIND_PLANS)
             for plan in table.values()})


# Setup-only exact basis aliases: one data view, one unstack per basis axis.
_O18_BASIS_SETUP = [False]
_O18_BASIS_PARENT_VIEWS = _rs_basis_views
_O18_BASIS_PARENT_BIND = _ASH_PARENT_BIND
_O18_BASIS_STATS = dict(calls=0, requested_calls_saved=0)

def _rs_basis_views(kind, L, T):
    if not _O18_BASIS_SETUP[0] or kind not in (0, 1, 2) or L < 2:
        return _O18_BASIS_PARENT_VIEWS(kind, L, T)
    data = slice(0, 7, 2) if kind == 0 else slice(0, 4)
    index = [data] * L
    if kind == 2:
        index[L - 1] = slice(None)
    common = T[tuple(index)]
    lo, hi = (2, 3) if kind == 0 else (1, 3)
    pairs = []
    for j in range(2, L + 1):
        parts = fnp.unstack(common, axis=L - j)
        pairs.append((parts[lo], parts[hi]))
    # The enclosing _SetupAliasHold retains common and all unstack outputs
    # until its existing final flush. Only selected aliases survive in pairs.
    _O18_BASIS_STATS['calls'] += 1
    _O18_BASIS_STATS['requested_calls_saved'] += L - 2
    return pairs

def _o18_basis_setup_bind(t0):
    old = _O18_BASIS_SETUP[0]
    environments = (_ASTRA_SM40_ENV, _SMX_ENV)
    saved = tuple(env._rs_basis_views for env in environments)
    _O18_BASIS_SETUP[0] = True
    for env in environments:
        env._rs_basis_views = _rs_basis_views
    try:
        return _O18_BASIS_PARENT_BIND(t0)
    finally:
        for env, original in zip(environments, saved):
            env._rs_basis_views = original
        _O18_BASIS_SETUP[0] = old

# This hook runs inside the existing alias-retention facade, never in predict.
_ASH_PARENT_BIND = _o18_basis_setup_bind


# Setup-only exact view memo: same live object, same view operation and arguments.
# Store only indices into the existing held list: its original clear releases
# every extra reference before the existing setup flush. Reshape is excluded.
_O18_MEMO_STATS = dict(hits=0, misses=0)
_O18_MEMO_BASE = _SetupAliasHold

def _o18_view_arg(value):
    if value is None or type(value) in (bool, int, float, str):
        return (type(value).__name__, value)
    if type(value) is slice:
        return ('slice', value.start, value.stop, value.step)
    if type(value) in (tuple, list):
        return (type(value).__name__, tuple(_o18_view_arg(x) for x in value))
    # The original facade retains args/results until setup's final clear.
    # Live identities therefore cannot be recycled within this dictionary.
    return ('identity', id(value))

class _SetupAliasHold(_O18_MEMO_BASE):
    def __init__(self, namespace):
        super().__init__(namespace)
        self._o18_view_memo = {}
        for name in ('transpose', 'moveaxis', 'swapaxes', 'unstack', 'split',
                     'squeeze', 'expand_dims', 'broadcast_to'):
            setattr(self, name, self._o18_memoized(name, getattr(self, name)))

    def _o18_memoized(self, name, original):
        def view(*args, **kwargs):
            key = (name, _o18_view_arg(args),
                   tuple((k, _o18_view_arg(v)) for k, v in sorted(kwargs.items())))
            index = self._o18_view_memo.get(key)
            if index is not None:
                _O18_MEMO_STATS['hits'] += 1
                return self.held[index][2]
            index = len(self.held)
            result = original(*args, **kwargs)
            self._o18_view_memo[key] = index
            _O18_MEMO_STATS['misses'] += 1
            return result
        return view

# October18: setup-only prefix batches of already-defined mainread operation views.
_O18_MRP_PARENT = _mr_bind_side_prefix_group_v1
_O18_MRP_BIND_PARENT = _ASH_PARENT_BIND
_O18_MRP_SETUP = [False]
_O18_MRP_STATS = dict(groups=0, keys=0)

def _mr_bind_side_prefix_group_v1(ker, kind, frame, requests):
    M, L, family = ker.M, frame['L'], ker.family[0]
    if not _O18_MRP_SETUP[0] or family != 'L5_narrow20' or L != 5 or kind not in (0, 1):
        return _O18_MRP_PARENT(ker, kind, frame, requests)
    u = 1 << L
    requests = tuple(sorted(set(tuple(map(int, x)) for x in requests)))
    requests = tuple(x for x in requests if (family, kind, L) + x not in M._sm40_cache)
    if not requests:
        return (0, 0, 0)
    points = tuple((P, rows // u, cols // u) for P, rows, cols in requests)
    capacity = (frame['P'], frame['rows'], frame['cols'])
    assert all(rows % u == 0 and cols % u == 0 for P, rows, cols in requests)
    assert all(all(0 < x <= y for x, y in zip(point, capacity)) for point in points)
    calls, schedule = _mr_prefix_schedule_v1(points, capacity)
    # Static geometry only: restrict to the dense A13/B9 cohorts. The bound
    # includes full-side construction before batching, so smaller groups keep
    # their original view construction and cannot regress this estimate.
    coefficient = 3 if kind == 0 else 4
    if len(points) < 8 or coefficient * len(points) <= (coefficient + 1) * calls + coefficient:
        return _O18_MRP_PARENT(ker, kind, frame, requests)
    selected_frame = M._sm40_frames[family]['sides'][kind]
    if kind == 1:
        selected_frame = M._sm40_compact_b.get((family, capacity[2]), selected_frame)
    assert selected_frame is frame
    T, chunks, G, basis, ops = ker.side(kind, L, capacity[0], capacity[1] * u, capacity[2] * u)
    wanted = (4, 6) if kind == 0 else (1, 3)
    arrays = {}
    def keep(value):
        arrays[id(value)] = value
    keep(T)
    keep(G)
    for lo, hi in basis:
        keep(lo)
        keep(hi)
    for index in wanted:
        keep(chunks[1][index])
    for operation, x, y, out in ops:
        keep(x)
        keep(y)
        keep(out)
    views = {}
    for ident, owner in arrays.items():
        ndim = len(owner.shape)
        if ndim == 2 * L + 2:
            axes = (1, L + 1, 2 * L + 1)  # G, or a slice preserving its chunk axis
        elif ndim == 2 * L + 1:
            axes = (0, L, 2 * L)          # A single first-level G chunk
        else:
            axes = (ndim - 3, ndim - 2, ndim - 1)
        assert tuple(int(owner.shape[axis]) for axis in axes) == capacity
        views[ident] = _mr_prefix_apply_v1(owner, axes, schedule)
    for request, point in zip(requests, points):
        def view(value):
            return views[id(value)][point]
        first = [None] * 7
        for index in wanted:
            first[index] = view(chunks[1][index])
        short = [None] * (L + 1)
        short[1] = tuple(first)
        M._sm40_cache[(family, kind, L) + request] = (
            view(T), short, view(G),
            [(view(lo), view(hi)) for lo, hi in basis],
            [(operation, view(x), view(y), view(out)) for operation, x, y, out in ops])
    _O18_MRP_STATS['groups'] += 1
    _O18_MRP_STATS['keys'] += len(points)
    original = sum(point != capacity for point in points)
    return (len(points), original * (3 * L - 2), calls * (3 * L - 2))

def _o18_mainread_prefix_bind(t0):
    old = _O18_MRP_SETUP[0]
    _O18_MRP_SETUP[0] = True
    try:
        return _O18_MRP_BIND_PARENT(t0)
    finally:
        _O18_MRP_SETUP[0] = old
_ASH_PARENT_BIND = _o18_mainread_prefix_bind

# Optional setup-only C-pair alias reuse. Same views; no arithmetic.
_O18_CPAIR_SETUP = [False]
_O18_CPAIR_PARENT = _l3o_pairs
_O18_CPAIR_BIND_PARENT = _ASH_PARENT_BIND
_O18_CPAIR_STATS = dict(calls=0, requested_calls_saved=0)

def _l3o_pairs(slot, L):
    if not _O18_CPAIR_SETUP[0]:
        return _O18_CPAIR_PARENT(slot, L)
    G = slot[0]
    order = list(range(1, L + 1)) + [0] + list(range(L + 1, 2 * L + 1))
    view = fnp.transpose(G, order)
    prefix = (slice(None),) * L
    pairs = (view[prefix + (slice(0, 6, 5),)],
             view[prefix + (slice(2, 4),)])
    _BH_HOLD.append((G, view, pairs))
    slot[0] = None
    _L3O_STATS['pairs'] += 1
    pairs = _TerminalPairs(pairs, G[0:5:4], G[5:7])
    slot[1] = pairs
    _O18_CPAIR_STATS['calls'] += 1
    _O18_CPAIR_STATS['requested_calls_saved'] += 1
    return pairs

def _o18_cpair_setup_bind(t0):
    previous = _O18_CPAIR_SETUP[0]
    _O18_CPAIR_SETUP[0] = True
    try:
        return _O18_CPAIR_BIND_PARENT(t0)
    finally:
        _O18_CPAIR_SETUP[0] = previous

_ASH_PARENT_BIND = _o18_cpair_setup_bind

# October18 exact-layout runtime repair. Capacity/strides only: preserve every
# public-tariff choice, actual body, orientation, L/P, call debit and arithmetic.
_O18_LAYOUT_FAMILIES = (('o18layout_L6P10_5_5_26', 6, 10, 5, 5, 26), ('o18layout_L6P20_5_5_16', 6, 20, 5, 5, 16), ('o18layout_L6P20_5_5_17', 6, 20, 5, 5, 17), ('o18layout_L5P40_9_9_24', 5, 40, 9, 9, 24), ('o18layout_L5P40_9_9_33', 5, 40, 9, 9, 33))
_O18_LAYOUT_KEYS = {family[1:]: family[0] for family in _O18_LAYOUT_FAMILIES}
for _o18_layout_family in _O18_LAYOUT_FAMILIES:
    _smx_register(_o18_layout_family)
_O18_UNION_NEW_FAMILIES = tuple(_O18_UNION_NEW_FAMILIES) + _O18_LAYOUT_FAMILIES

def _o18_exact_layout_plan(plan):
    old_family = _SMX_FAMILIES[plan[1]]
    L, P = old_family[1:3]
    axes = _SMX_RECORDS[plan[0]]['shape']
    u = 1 << L
    actual = tuple((int(x) + int(g) * u - 1) // (int(g) * u)
                   for x, g in zip(plan[2:5], axes))
    target = _O18_LAYOUT_KEYS.get((L, P) + actual)
    if target is None:
        return plan
    new_family = _SMX_FAMILIES[target]
    assert old_family[1:3] == new_family[1:3]
    assert tuple(new_family[3:]) == actual
    assert all(a <= b for a, b in zip(actual, old_family[3:]))
    return (plan[0], target) + tuple(plan[2:])

_O18_UNION_RULES = {key: tuple((gain, cost, _o18_exact_layout_plan(plan))
                              for gain, cost, plan in options)
                    for key, options in _O18_UNION_RULES.items()}
_O18_UNION_BIND_PLANS = {index: _o18_exact_layout_plan(plan)
                        for index, plan in _O18_UNION_BIND_PLANS.items()}
_SETUP_PEEL_SIDE_GROUPS_V1 = _SETUP_PEEL_SIDE_GROUPS_V1 | frozenset(
    (family[0], kind) for family in _O18_LAYOUT_FAMILIES for kind in (1, 2))

_O18_SHARED_RESTORE_SHAPES = ((384, 960, 6144), (768, 6144, 384), (384, 832, 5568))
for _o18_restore_shape in _O18_SHARED_RESTORE_SHAPES:
    _o18_restore_plan = _O18_SHARED_ORIGINAL_PLANS[_o18_restore_shape]
    _o18_restore_gain, _o18_restore_cost, _o18_current_plan = _O18_SHARED_RULES[_o18_restore_shape]
    assert _o18_restore_plan[0] == _o18_current_plan[0]
    assert _o18_restore_plan[2:] == _o18_current_plan[2:5]
    assert _SMX_FAMILIES[_o18_restore_plan[1]][1:3] == _SMX_FAMILIES[_o18_current_plan[1]][1:3]
    # Runtime full plan retains its original fringe recipes (these five are
    # complete bodies). Setup inventory retains the five-field body contract.
    _O18_SHARED_RULES[_o18_restore_shape] = (
        _o18_restore_gain, _o18_restore_cost,
        (_o18_current_plan[0], _o18_restore_plan[1]) + tuple(_o18_current_plan[2:]))
    _O18_SHARED_PLANS[_o18_restore_shape] = _o18_restore_plan
    assert _o18_restore_shape not in _SM12_RULE
    _SM12_PLANS[_o18_restore_shape] = _o18_restore_plan
_O18_SHARED_FAMILIES = tuple(_SMX_FAMILIES[name] for name in sorted(
    {plan[1] for plan in _O18_SHARED_PLANS.values()}))


# Setup-only reuse of byte-identical A frames, A sides and prefix aliases.
_O18_ALIAS_REUSE_SETUP = [False]
_O18_ALIAS_REUSE_FRAME_PARENT = _astra_sm40_bind_family
_O18_ALIAS_REUSE_SIDE_PARENT = _SmxKernel.side
_O18_ALIAS_REUSE_PREFIX_PARENT = _peel_side_prefixes
_O18_ALIAS_REUSE_BIND_PARENT = _ASH_PARENT_BIND
_O18_A_FRAME_CACHE = {}
_O18_A_SIDE_CACHE = {}
_O18_PREFIX_ALIAS_CACHE = {}

def _astra_sm40_bind_family(fnp, module, arena, family, extra_c=None, shared_c=None):
    if not _O18_ALIAS_REUSE_SETUP[0] or module is not _SMX_ENV:
        return _O18_ALIAS_REUSE_FRAME_PARENT(fnp, module, arena, family, extra_c, shared_c)
    name, L, P, r, k, c = family
    sides = []
    offset = 0
    akey = (id(arena), L, P, r, k)
    cached = _O18_A_FRAME_CACHE.get(akey)
    if cached is not None:
        assert cached[0] is arena
    # One public split produces the original three exact contiguous pieces.
    pieces = None
    if extra_c is None and shared_c is None:
        na, nb, nc = (7 ** L * P * x for x in (r * k, k * c, r * c))
        assert na + nb + nc <= int(arena.shape[0])
        pieces = fnp.split(arena, (na, na + nb, na + nb + nc), axis=0)
    for kind, (rr, cc) in enumerate(((r, k), (k, c), (r, c))):
        if kind == 2 and shared_c is not None:
            sides.append(shared_c)
            continue
        count = 7 ** L * P * rr * cc
        owner = extra_c if kind == 2 and extra_c is not None else arena
        start = 0 if owner is extra_c else offset
        assert start + count <= int(owner.shape[0])
        if kind == 0 and cached is not None:
            sides.append(cached[1])
            offset += count
            continue
        piece = pieces[kind] if pieces is not None else owner[start:start + count]
        T = fnp.reshape(piece, (7,) * L + (P, rr, cc))
        if owner is arena:
            offset += count
        data = slice(0, 7, 2) if kind == 0 else slice(0, 4)
        levels = [None, None]
        for j in range(2, L + 1):
            nr = L - j
            level = T[(data,) * nr] if nr else T
            levels.append(fnp.moveaxis(level, nr, 0) if nr else level)
        nr = L - 1
        raw = T[(data,) * nr]
        view = fnp.reshape(raw, (2, 2) * nr + (7, P, rr, cc))
        swap = [x for q in range(nr) for x in (2 * q + 1, 2 * q)] if kind == 2 else list(range(2 * nr))
        base = swap + list(range(2 * nr, 2 * nr + 4))
        G = fnp.transpose(view, [base[x] for x in module._rs_nat_perm(L, 1)])
        side = dict(T=T, levels=levels, G=G, basis=module._rs_basis_views(kind, L, T), L=L, P=P, rows=rr, cols=cc)
        sides.append(side)
        if kind == 0:
            _O18_A_FRAME_CACHE[akey] = (arena, side)
    return dict(name=name, owner=arena, family=family, sides=tuple(sides), elements=offset)

def _o18_reused_a_side(self, kind, L, P, rows, cols):
    if not _O18_ALIAS_REUSE_SETUP[0] or self.M is not _SMX_ENV or kind != 0:
        return _O18_ALIAS_REUSE_SIDE_PARENT(self, kind, L, P, rows, cols)
    frame = self.M._sm40_frames[self.family[0]]['sides'][0]
    shared_key = (id(frame), L, P, rows, cols)
    actual_key = (self.family[0], kind, L, P, rows, cols)
    if actual_key in self.M._sm40_cache:
        result = self.M._sm40_cache[actual_key]
        _O18_A_SIDE_CACHE.setdefault(shared_key, (frame, result))
        return result
    found = _O18_A_SIDE_CACHE.get(shared_key)
    if found is not None:
        assert found[0] is frame
        self.M._sm40_cache[actual_key] = found[1]
        return found[1]
    result = _O18_ALIAS_REUSE_SIDE_PARENT(self, kind, L, P, rows, cols)
    _O18_A_SIDE_CACHE[shared_key] = (frame, result)
    return result

_SmxKernel.side = _o18_reused_a_side

def _peel_side_prefixes(owner, pairs, axes):
    if not _O18_ALIAS_REUSE_SETUP[0]:
        return _O18_ALIAS_REUSE_PREFIX_PARENT(owner, pairs, axes)
    pairs = tuple(sorted(set(tuple(pair) for pair in pairs)))
    axes = tuple(int(axis) % len(owner.shape) for axis in axes)
    key = (id(owner), axes)
    found = _O18_PREFIX_ALIAS_CACHE.get(key)
    if found is None:
        found = (owner, {})
        _O18_PREFIX_ALIAS_CACHE[key] = found
    assert found[0] is owner
    saved = found[1]
    missing = tuple(pair for pair in pairs if pair not in saved)
    if missing:
        saved.update(_O18_ALIAS_REUSE_PREFIX_PARENT(owner, missing, axes))
    return {pair: saved[pair] for pair in pairs}

def _o18_alias_reuse_bind(t0):
    assert not _O18_ALIAS_REUSE_SETUP[0]
    _O18_ALIAS_REUSE_SETUP[0] = True
    try:
        return _O18_ALIAS_REUSE_BIND_PARENT(t0)
    finally:
        _O18_ALIAS_REUSE_SETUP[0] = False
        _O18_A_FRAME_CACHE.clear()
        _O18_A_SIDE_CACHE.clear()
        _O18_PREFIX_ALIAS_CACHE.clear()

_ASH_PARENT_BIND = _o18_alias_reuse_bind


# Prediction-only exact basis alias batching. Setup retains its existing facade.
_O18_RUNTIME_BASIS_PARENT = _rs_basis_views

def _rs_basis_views(kind, L, T):
    if _O18_BASIS_SETUP[0] or kind not in (0, 1, 2) or L < 4:
        return _O18_RUNTIME_BASIS_PARENT(kind, L, T)
    data = slice(0, 7, 2) if kind == 0 else slice(0, 4)
    index = [data] * L
    if kind == 2:
        index[L - 1] = slice(None)
    common = T[tuple(index)]
    retained = [common]
    lo, hi = (2, 3) if kind == 0 else (1, 3)
    pairs = []
    for j in range(2, L + 1):
        parts = fnp.unstack(common, axis=L - j)
        retained.append(parts)
        pairs.append((parts[lo], parts[hi]))
    # Keep ALL unstack outputs, including unused views, through the current
    # outer kernel's established _BH_HOLD cleanup. No per-level free drains.
    # The selected pair views also survive independently in the tree cache.
    _BH_HOLD.append(retained)
    return pairs

# A P40 body consumes the whole forty-product stack. Empty-cut split is
# exactly one full-range view; reuse its existing owner during setup.
def _setup_peel_outer_prefixes_v1(cases):
    env = _SMX_ENV
    groups = {}
    for ker, family, L, P, cm, ck, cn in cases:
        key = (family, L, cm, ck, cn, P)
        if key not in env._sm40_outer_cache:
            groups.setdefault(family, {})[key] = (cm, ck, cn, P)
    for family, jobs in groups.items():
        owners = env._smx_outer[family]
        av = _peel_side_prefixes(owners['A'], ((m, k) for m, k, n, p in jobs.values()), (1, 2))
        bv = _peel_side_prefixes(owners['B'], ((k, n) for m, k, n, p in jobs.values()), (1, 2))
        cv = _peel_side_prefixes(owners['C'], ((m, n) for m, k, n, p in jobs.values()), (1, 2))
        for key, (m, k, n, P) in jobs.items():
            LA, RB, PC = av[m, k], bv[k, n], cv[m, n]
            pc = tuple(fnp.unstack(PC, axis=0))
            cuts = list(range(P, 40, P))
            parts = tuple(zip(fnp.split(LA, cuts, axis=0), fnp.split(RB, cuts, axis=0), fnp.split(PC, cuts, axis=0))) if cuts else ((LA, RB, PC),)
            env._sm40_outer_cache[key] = (LA, RB, PC, pc, parts)


# Setup-only GTA inventory: batch existing contiguous arena slices, not trees.
# Preserve every original reshape, layout class, shape, cache key and order.
def _gta_prepare():
    if _SCRATCH is None:
        return
    arena = _SCRATCH[0]
    if _GCV_OWNER[0] is not arena:
        return
    tasks = []
    seen = set(_GCV_TREES)
    for kind, L, rows, cols in _PB_SINGLE:
        if dict.get((_IPT_A, _IPT_B, _IPT_C)[kind], (L, rows, cols)) is not None:
            continue
        u = 1 << L
        r, c = rows // u, cols // u
        box = _LB_BOX.get(kind)
        if (L == 6 and box is not None and box['arena'] is arena
                and r <= box['R'] and c <= box['C']
                and (kind, L, rows, cols) not in _LB_SETUP_KEYS
                and not (kind == 1 and rows in (256, 384))):
            continue
        region = _IPT_REGION[L]
        start = (0, region[0], region[0] + region[1])[kind]
        shape = (7,) * L + (r, c)
        key = (start, shape)
        if key in seen or key in _O18_SETUP_DROP_GTA_ROOTS:
            continue
        seen.add(key)
        count = 7 ** L * r * c
        interval = (start, start + count)
        tasks.append((key, shape, interval))
    if tasks:
        pieces = _peel_split_ranges(arena, (task[2] for task in tasks), axis=0)
        for key, shape, interval in tasks:
            tree = fnp.reshape(pieces[interval], shape)
            _GCV_TREES[key] = (arena, tree)
    _GTA_STATS['prepared'] = len(tasks)

