# Exact runtime version of the established setup C-pair alias construction.
# Only view construction changes: no arithmetic or terminal update changes.
_O18_RUNTIME_CPAIR_PARENT = _l3o_pairs

def _l3o_pairs(slot, L):
    if _O18_CPAIR_SETUP[0]:
        return _O18_RUNTIME_CPAIR_PARENT(slot, L)
    G = slot[0]
    order = list(range(1, L + 1)) + [0] + list(range(L + 1, 2 * L + 1))
    view = fnp.transpose(G, order)
    prefix = (slice(None),) * L
    pairs = (view[prefix + (slice(0, 6, 5),)],
             view[prefix + (slice(2, 4),)])
    # Retain the parent and intermediate through the existing kernel cleanup;
    # cached pair views keep their own persistent references as before.
    _BH_HOLD.append((G, view, pairs))
    slot[0] = None
    _L3O_STATS['pairs'] += 1
    pairs = _TerminalPairs(pairs, G[0:5:4], G[5:7])
    slot[1] = pairs
    return pairs

# Setup repair: keep all numerical families and arithmetic; defer only union
