def _o18_setup_io_grid(plan):
    record,family,m,k,n=plan[:5]
    _,L,P,*_=_SMX_FAMILIES[family]
    u=1<<L;axes=_SMX_RECORDS[record]['shape']
    cm,ck,cn=tuple(((int(x)+int(a)*u-1)//(int(a)*u))*u
                   for x,a in zip((m,k,n),axes))
    return (family,L,cm,ck,cn,P)

# Shared/SM12 IO is retained even if a future inventory overlaps a union grid.
_O18_SETUP_DEFER_IO = frozenset(
    _o18_setup_io_grid(p) for p in _O18_UNION_BIND_PLANS.values()) - frozenset(
    _o18_setup_io_grid(p) for p in _SM12_PLANS.values())
_O18_SETUP_IO_IN_BIND = [False]
_O18_SETUP_IO_STATS = dict(setup_skipped=0,cold_grids=0)
_O18_SETUP_IO_PARENT_BIND = _ASH_PARENT_BIND
def _o18_setup_io_bind(t0):
    _O18_SETUP_IO_IN_BIND[0]=True
    try:
        return _O18_SETUP_IO_PARENT_BIND(t0)
    finally:
        _O18_SETUP_IO_IN_BIND[0]=False
_ASH_PARENT_BIND = _o18_setup_io_bind

_O18_SETUP_IO_PARENT_PREPARE = _peel_prebind_batch_io
def _peel_prebind_batch_io(ker,key):
    if (_O18_SETUP_IO_IN_BIND[0] and ker.M is _SMX_ENV
            and key in _O18_SETUP_DEFER_IO):
        # Preserve every side-transform alias that the original IO preparer
        # would have warmed (including cropped A sides not in B/C batching).
        family,level,rows,inner,cols,batch=key
        assert ker.family[0] == family
        ker.side(0,level,batch,rows,inner)
        ker.side(1,level,batch,inner,cols)
        ker.side(2,level,batch,rows,cols)
        _O18_SETUP_IO_STATS['setup_skipped']+=1
        return
    return _O18_SETUP_IO_PARENT_PREPARE(ker,key)


# Preserve the original first128 packed classification even for aliases deferred
# until first actual use. This set is exactly what baseline setup would add.
_O18_SETUP_SKIP_PREFIX = frozenset(((2, 6, 1024, 640), (1, 6, 960, 640), (1, 6, 960, 2048)))
_O18_SETUP_RARE_RF = frozenset()  # Restore the seven observed RF keys in setup.
assert _O18_SETUP_SKIP_PREFIX.issubset(set(_PB_SINGLE[:128]))
assert _O18_SETUP_RARE_RF.issubset(set(_PB_SINGLE[128:_RF192_PREFIX]))
_LB_SETUP_KEYS.update(_PB_SINGLE[:128])
_O18_SETUP_SKIP_RF = _O18_SETUP_SKIP_RF | _O18_SETUP_RARE_RF
_O18_SETUP_DEFER_FULL = _O18_SETUP_SKIP_RF | _O18_SETUP_SKIP_PREFIX
_O18_SETUP_DEFER_PARENT_SIDE = _ipt_side
_O18_SETUP_DEFER_CACHES = (_IPT_A,_IPT_B,_IPT_C)
_O18_SETUP_DEFER_STATS = dict(first_uses=0)
def _ipt_side(kind,L,rows,cols):
    key=(kind,L,rows,cols)
    if (key not in _O18_SETUP_DEFER_FULL or _O18_SETUP_IO_IN_BIND[0]
            or (_IPT_A,_IPT_B,_IPT_C)[kind] is not _O18_SETUP_DEFER_CACHES[kind]):
        return _O18_SETUP_DEFER_PARENT_SIDE(kind,L,rows,cols)
    cache=(_IPT_A,_IPT_B,_IPT_C)[kind]
    entry=dict.get(cache,(L,rows,cols))
    if entry is not None and entry[3] is not None:
        # The usual parent path retains normal cache recency and wrappers.
        return _O18_SETUP_DEFER_PARENT_SIDE(kind,L,rows,cols)
    saved_eager=_LVF_EAGER[0]
    _LVF_EAGER[0]=True
    try:
        entry=_O18_SETUP_DEFER_PARENT_SIDE(kind,L,rows,cols)
        assert entry[3] is not None
        slot=entry[2]
        if type(slot) is list and slot[1] is None:
            _l3o_pairs(slot,L) if kind==2 else _l3_quad(slot,kind,L)
        _O18_SETUP_DEFER_STATS['first_uses']+=1
        return entry
    finally:
        _LVF_EAGER[0]=saved_eager

# Final small setup-margin cut: six rare public-shape full bindings.
# The existing v4 first-use wrapper retains original class/eager operations.
_O18_SETUP_FINAL_RF = frozenset()  # Restore these six original RF binds during setup.
assert _O18_SETUP_FINAL_RF.issubset(set(_PB_SINGLE[128:_RF192_PREFIX]))
_O18_SETUP_SKIP_RF = _O18_SETUP_SKIP_RF | _O18_SETUP_FINAL_RF
_O18_SETUP_DEFER_FULL = _O18_SETUP_SKIP_RF | _O18_SETUP_SKIP_PREFIX

# Setup-only collection batching. Keep all public setup work and the parent's
# complete end-of-setup collect/freeze inside the official startup budget.
_O18_SETUPGC_PARENT = Estimator.setup
def _o18_setupgc_v1(self, context):
    thresholds = _setup_gc.get_threshold()
    _setup_gc.set_threshold(14000, 20, thresholds[2])
    try:
        return _O18_SETUPGC_PARENT(self, context)
    finally:
        _setup_gc.set_threshold(*thresholds)
Estimator.setup = _o18_setupgc_v1

# The two side wrappers only mark a binding context on a cache miss. A hit
# preserves exactly the original single LRU get and needs neither context.
# All setup calls and exceptional non-fused deferred entries use the parent.
_O18_SIDE_HIT_PARENT = _ipt_side
def _ipt_side(kind, L, rows, cols):
    if _LB_SETUP[0] or _O18_SETUP_IO_IN_BIND[0]:
        return _O18_SIDE_HIT_PARENT(kind, L, rows, cols)
    cache = (_IPT_A, _IPT_B, _IPT_C)[kind]
    entry = cache.get((L, rows, cols))
    if entry is not None:
        if (entry[3] is not None
                or cache is not _O18_SETUP_DEFER_CACHES[kind]
                or (kind, L, rows, cols) not in _O18_SETUP_DEFER_FULL):
            return entry
    return _O18_SIDE_HIT_PARENT(kind, L, rows, cols)

# Fixed public-tariff policy: choose maximal saved FLOPs minus2MF per added
# request among affordable existing plans. All existing setup inventory stays
# fixed; no new family, body, layout, or cold-binding route is introduced.
_O18_REQUEST_PENALTY = 2_000_000
_O18_REQUEST_POLICY_PARENT = _O18_UNION_RULES
_O18_UNION_RULES = {
    key: tuple(sorted(
        (option for option in options
         if option[0] >= _O18_REQUEST_PENALTY * option[1]),
        key=lambda option: (-(option[0] - _O18_REQUEST_PENALTY * option[1]),
                            option[1], -option[0])))
    for key, options in _O18_REQUEST_POLICY_PARENT.items()
}

