# Setup-only contiguous GCV root slices. Identical reshapes, owners and classes.
# The original function still owns level1/quad construction and all eligibility.
_O18_GCV_ROOT_PARENT = _gcv_prepare

def _gcv_prepare(prefix=280):
    if _SCRATCH is None:
        return _O18_GCV_ROOT_PARENT(prefix)
    arena = _SCRATCH[0]
    if _GCV_OWNER[0] is not arena:
        _gcv_clear()
        _GCV_OWNER[0] = arena
    tasks = []
    seen = set(_GCV_TREES)
    for kind, L, rows, cols in _PB_SINGLE[:prefix]:
        cache = (_IPT_A, _IPT_B, _IPT_C)[kind]
        if dict.get(cache, (L, rows, cols)) is not None:
            continue
        u = 1 << L
        r, c = rows // u, cols // u
        box = _LB_BOX.get(kind)
        if (L == 6 and box is not None and box['arena'] is arena
                and r <= box['R'] and c <= box['C']
                and (kind, L, rows, cols) not in _LB_SETUP_KEYS
                and not (kind == 1 and rows in (256, 384))):
            continue
        region = _IPT_REGION[L]
        start = (0, region[0], region[0] + region[1])[kind]
        shape = (7,) * L + (r, c)
        key = (start, shape)
        if key in seen:
            continue
        seen.add(key)
        count = 7 ** L * r * c
        tasks.append((key, shape, (start, start + count)))
    if tasks:
        pieces = _peel_split_ranges(arena, (task[2] for task in tasks), axis=0)
        for key, shape, interval in tasks:
            piece = pieces[interval]
            tree = fnp.reshape(piece, shape)
            _BH_HOLD.append((piece, tree))
            _GCV_TREES[key] = (arena, tree)
            _GCV_STATS['trees'] += 1
    return _O18_GCV_ROOT_PARENT(prefix)

# Retain reference counting; defer only automatic cyclic scans during setup.
# The unchanged parent still performs full collect()+freeze() before returning.
_O18_SETUP_GC_ONCE_PARENT = Estimator.setup

def _o18_setup_gc_once(self, context):
    enabled = _setup_gc.isenabled()
    _setup_gc.disable()
    try:
        return _O18_SETUP_GC_ONCE_PARENT(self, context)
    finally:
        if enabled:
            _setup_gc.enable()
        else:
            _setup_gc.disable()

Estimator.setup = _o18_setup_gc_once

# Exact setup-only retention: these view APIs retain their sole array argument
# and result. Shape/axis arguments and keyword dictionaries contain no array
# owners and need not survive every setup call. Memo result slot2 is unchanged.
def _o18_lean_setup_wrap_v1(self, operation):
    held, calls = self.held, self._calls
    def view(*args, **kwargs):
        result = operation(*args, **kwargs)
        owner = args[0] if args else kwargs
        held.append((owner, None, result))
        calls[0] += 1
        return result
    return view

_SetupAliasHold.wrap = _o18_lean_setup_wrap_v1


# Setup-only exact group-workspace node sharing. All node workspaces start at
# arena offset zero; for a fixed (rows,cols), old unstack tuples are prefixes of
# the same physical planes. Group batches and program/cache identities remain
# separate, and all original group offsets are retained.
def _setup_peel_group_prefixes_v1(cases):
    env = _SMX_ENV
    jobs = {}
    for ker, family, L, P, cm, ck, cn in cases:
        for kind, shape in (("L", (cm, ck)), ("R", (ck, cn)), ("P", (cm, cn))):
            key = (ker.record["name"], kind, shape)
            if key in env._sm40_group_cache or key in jobs:
                continue
            sizes = tuple(len(nodes) for _, nodes in ker.circuits[kind][1])
            jobs[key] = (sizes, sum(sizes), shape)
    if not jobs:
        return
    arena = env._SCRATCH[0]
    pieces = _peel_split_ranges(arena,
        ((0, total * shape[0] * shape[1])
         for sizes, total, shape in jobs.values()), 0)
    allnodes_by_key = {}
    maximal_by_shape = {}
    for key, (sizes, total, (rows, cols)) in jobs.items():
        allnodes = fnp.reshape(pieces[0, total * rows * cols],
                               (total, rows, cols))
        allnodes_by_key[key] = allnodes
        shape = (rows, cols)
        previous = maximal_by_shape.get(shape)
        if previous is None or total > previous[0]:
            maximal_by_shape[shape] = (total, allnodes)
    node_pools = {shape: tuple(fnp.unstack(allnodes, axis=0))
                  for shape, (total, allnodes) in maximal_by_shape.items()}
    for key, (sizes, total, shape) in jobs.items():
        cuts = []
        at = 0
        for size in sizes[:-1]:
            at += size
            cuts.append(at)
        batches = tuple(fnp.split(allnodes_by_key[key], cuts, axis=0))
        # Python tuple slicing creates no public array operation.
        node_views = node_pools[shape][:total]
        env._sm40_group_cache[key] = _Sm40Prepared((batches, node_views))

# Exact setup sharing of identical outer/padding aliases across families.
def _smx_bind():
    env, arena = _SMX_ENV, _SCRATCH[0]
    base = _ASTRA_SM40_ENV
    # Setup-local interning of exact physical aliases. Same backing object,
    # byte offset, shape and C strides; no kernel layout or numeric copy changes.
    physical_aliases = {}
    def prefix_reshape(owner, start, count, shape):
        shape = tuple(shape)
        key = (id(owner), int(start), int(count), shape)
        found = physical_aliases.get(key)
        if found is not None:
            assert found[0] is owner
            return found[1]
        value = fnp.reshape(owner[start:start + count], shape)
        physical_aliases[key] = (owner, value)
        return value
    assert base._sm40_owner is arena
    env._sm40_owner = None
    env._sm40_cache, env._sm40_io_cache, env._sm40_outer_cache, env._sm40_group_cache = {}, {}, {}, {}
    env._peel_batch_destination_cache = {}
    env._peel_batch_operand_cache = {}
    env._smx_prepared = None
    env._sm12_prepared = None
    env._sm40_frames = {name: _astra_sm40_bind_family(fnp, env, arena, f) for name, f in _SMX_FAMILIES.items()}
    dims = {name: (f[3] << f[1], f[4] << f[1], f[5] << f[1]) for name, f in _SMX_FAMILIES.items()}
    owners = sorted((fnp.reshape(x, (-1,)) for x in base._sm40_outer.values()), key=lambda x: int(x.shape[0]))
    pad = base._sm40_extra_leaf
    orientations = {}
    for plan in tuple(_PEEL_PUSH_PLANS.values()) + tuple(_PEEL_READ_PLANS.values()):
        orientations.setdefault(plan[1], set()).add(tuple(_SMX_RECORDS[plan[0]]['shape']))
    env._smx_outer, env._smx_padding = {}, {}
    for name, (r, k, c) in dims.items():
        shapes = dict(A=(40,r,k), B=(40,k,c), C=(40,r,c))
        ordered = sorted(shapes, key=lambda x: _rc_math.prod(shapes[x]))
        views = {}
        for side, owner in zip(ordered, owners):
            shape=shapes[side];count=_rc_math.prod(shape)
            assert count <= int(owner.shape[0]), (name,side,count,int(owner.shape[0]))
            views[side]=prefix_reshape(owner,0,count,shape)
        env._smx_outer[name]=views
        caps=orientations.get(name,((6,6,6),))
        # Each family is orientation-specific in the frozen plans; max supports safe future reuse.
        am=max(ar*r for ar,ak,an in caps);ak=max(ak*k for ar,ak,an in caps)
        bk=max(qk*k for ar,qk,an in caps);bn=max(an*c for ar,qk,an in caps)
        na,nb=am*ak,bk*bn
        assert na+nb <= int(pad.shape[0]), (name,na+nb,int(pad.shape[0]))
        env._smx_padding[name]=((prefix_reshape(pad,0,na,(am,ak)),prefix_reshape(pad,na,nb,(bk,bn))),{}, {})
    env._sm40_extra_leaf_bytes=0
    env._SCRATCH=_SCRATCH
    env._sm40_owner=arena
    _SMX_STATS['binds']+=1


# Exact setup constant-row batching. No coefficient arithmetic is changed.
# Five parameter tables are read-only. Unstack returns the same contiguous row
# views as indexing; their lifetime is the existing per-P/per-width GNN state.
_O18_CONSTROWS_PARENT_GNN_LAYER = _e2_gnn_layer
_O18_CONSTROWS_PARENT_FEATURE = _e2_feature_columns

def _e2_gnn_layer(k, l):
    c = k['layers'].get(l)
    if c is not None:
        return c
    if type(l) is not int or not 1 <= l <= 15:
        return _O18_CONSTROWS_PARENT_GNN_LAYER(k, l)
    P = k['P']
    names = ('centers', 'scales', 'rms', 'head', 'head_b')
    if any(not P[name].shape or int(P[name].shape[0]) != 16 for name in names):
        return _O18_CONSTROWS_PARENT_GNN_LAYER(k, l)
    if c is None:
        rows = k.get('_o18_rows')
        if rows is None:
            rows = k['_o18_rows'] = {name: fnp.unstack(P[name]) for name in names}
        c = k['layers'][l] = dict(centers=rows['centers'][l], scales=rows['scales'][l],
                                  rms=rows['rms'][l], head=rows['head'][l],
                                  head_b=rows['head_b'][l],
                                  gain=1 + 0.25 * fnp.tanh(P['gain'][l:l + 1]))
    return c

def _e2_feature_columns(n, l):
    c = _E2_FEAT.get((n, l))
    if c is not None:
        return c
    if n != 1024 or type(l) is not int or not 1 <= l <= 15:
        return _O18_CONSTROWS_PARENT_FEATURE(n, l)
    if c is None:
        ones = _E2_FEAT.get(n)
        if ones is None:
            ones = _E2_FEAT[n] = fnp.ones(n)
        # Preserve Python scalar evaluation and binary64 multiply-by-one order.
        # All 30 rows are contiguous, writable owned output, consumed read-only.
        values = [value for layer in range(1, 16)
                  for value in (2 * layer / 15 - 1, layer / 16)]
        hold = _E2Hold()
        scalar_rows = hold(fnp.asarray(values, dtype=fnp.float64))
        column = hold(scalar_rows[:, None])
        matrix = hold(column * ones)
        rows = fnp.unstack(matrix)
        for layer in range(1, 16):
            _E2_FEAT.setdefault((n, layer), (rows[2 * (layer - 1)], rows[2 * (layer - 1) + 1], ones))
        c = _E2_FEAT[(n, l)]
    return c


