# Exact birth-head constant batching; setup only, no runtime controller change.
def _cs_build(n=1024, depth=16):
    global _GNN_PARAMS, _EDGE_PARAMETERS
    g = globals()
    hold = _E2Hold()   # temporaries of this call, released together
    if _GNN_PARAMS is None:                               # as _predict_learned_compact
        _GNN_PARAMS = _unpack_static_fp32(_GNN_LITERAL)
    P = _GNN_PARAMS
    if _MESSAGE_EDGE_ENABLED:
        _message_edge_parameters()
        if _EDGE_PARAMETERS is None:                      # as _message_edge_source
            _EDGE_PARAMETERS = {k: fnp.asarray(v, dtype=fnp.float32) for k, v in _EDGE_LITERAL.items()}
        _e2_edge_consts(_EDGE_PARAMETERS, n)
    _bdnh_parameters()
    cstar_all = _bd_coefficients()
    if depth == 16 and tuple(cstar_all.shape) == (15, 4):
        missing = [l for l in range(1, 15)
                   if l not in _E2_BDNH or _E2_BDNH[l][0] is not cstar_all]
        if missing:
            # Identical per-element float32 abs then 1-minus, evaluated once.
            # Unstack returns the same shape/stride rows as integer indexing.
            cstar_rows = hold(fnp.unstack(cstar_all))
            onem_all = hold(1 - hold(fnp.abs(cstar_all)))
            onem_rows = hold(fnp.unstack(onem_all))
            for l in missing:
                _E2_BDNH[l] = (cstar_all, cstar_rows[l], onem_rows[l])
    else:
        for l in range(1, depth - 1):
            c = _E2_BDNH.get(l)
            if c is None or c[0] is not cstar_all:
                cstar = cstar_all[l]
                _E2_BDNH[l] = (cstar_all, cstar, 1 - hold(fnp.abs(cstar)))
    k = _e2_gnn_consts(P, n)
    for l in range(1, depth):                             # gnn_step and features run at layers 1..15
        _e2_gnn_layer(k, l)
        _e2_feature_columns(n, l)
    st = _e2_pair_state(n)
    _e2_pair_arena(n)
    _psp_views(st, n)
    _e1gn_state(st, n)
    if '_bd32_state' in g:
        _bd32_state(n)
    _e2_wpow(hold(fnp.zeros((n, n), dtype=fnp.float32)))['W'] = None   # the stack and its views; the first layer's weights fill it
    if '_np_const' in g:
        _np_const(n)
    if '_f4c_const' in g:
        C = _f4c_const()
        if 'rowi' in C and ('one', n) not in C:           # F4c v2's row of ones
            C[('one', n)] = fnp.ones(n)
    if '_k4l_const' in g:
        C = _k4l_const()
        if 'idxA' in C and 'one' not in C:                # K4L v5's row of ones, as _k4l_birth
            C['one'] = fnp.ones(n, dtype=fnp.float64)


# Exact compact-portfolio capacity repair. The historic family name is retained
# so every runtime rule/cache lookup stays identical; its now-unused width41
# capacity is reduced to35. All active products retain their actual cm/ck/cn,
# orientation, recursion depth, batch size, fringe recipes and call debit.
_O18_COMPACT_CAPACITY_NAME = 'o18union_L5P40_9_9_41'
_O18_COMPACT_CAPACITY_OLD = _SMX_FAMILIES[_O18_COMPACT_CAPACITY_NAME]
assert _O18_COMPACT_CAPACITY_OLD == (_O18_COMPACT_CAPACITY_NAME, 5, 40, 9, 9, 41)
_O18_COMPACT_CAPACITY_NEW = (_O18_COMPACT_CAPACITY_NAME, 5, 40, 9, 9, 35)
for _o18_capacity_plan in tuple(_O18_UNION_BIND_PLANS.values()) + tuple(_SM12_PLANS.values()):
    if _o18_capacity_plan[1] == _O18_COMPACT_CAPACITY_NAME:
        assert _o18_capacity_plan[0] == 'signed_executable_0'
        assert all(int(x) <= a * 32 * leaf for x, a, leaf in
                   zip(_o18_capacity_plan[2:5], (3, 3, 6), (9, 9, 35)))
_SMX_FAMILIES[_O18_COMPACT_CAPACITY_NAME] = _O18_COMPACT_CAPACITY_NEW
# Keep retained inventory descriptors coherent; no new registry name/owner.
_O18_UNION_NEW_FAMILIES = tuple(
    _O18_COMPACT_CAPACITY_NEW if f[0] == _O18_COMPACT_CAPACITY_NAME else f
    for f in _O18_UNION_NEW_FAMILIES)
_O18_SHARED_FAMILIES = tuple(
    _O18_COMPACT_CAPACITY_NEW if f[0] == _O18_COMPACT_CAPACITY_NAME else f
    for f in _O18_SHARED_FAMILIES)

# Setup-only metadata diet. The original owner-retaining wrapper still executes
# every view call. Split memo and all other alias/shape caches remain unchanged.
# Measured broad-setup hit counts: unstack5/3117, transpose0/514,
# moveaxis0/743, swapaxes0/1. Repeating a view preserves physical alias geometry.
_O18_MEMO_DIET_PARENT_FACTORY = _SetupAliasHold._o18_memoized

def _o18_memo_diet_factory(self, name, original):
    if name in ('unstack', 'transpose', 'moveaxis', 'swapaxes'):
        return original
    return _O18_MEMO_DIET_PARENT_FACTORY(self, name, original)

_SetupAliasHold._o18_memoized = _o18_memo_diet_factory

# Same fixed analytic gate33 correction, fused into the incumbent polynomial call.
_GQ33_PARENT = _gq
_GQ33_CONST = {}
_GQ33_PREDICT_PARENT = Estimator.predict
_GQ33_STATS = dict(calls=0)

def _gq(g, d, aux, bpre):
    hold = _E2Hold()
    s = aux['sigma']
    S = _GQ33_CONST
    n = int(s.shape[0])
    if S.get('n') != n:
        o, G, A, P, I, K3, K4, D, B = range(9)
        terms = [((G,), 1.0), ((K3, I, I, I, A, A, P), _GSK / 6.0),
                 ((K3, I, I, I, P), -_GSK / 6.0),
                 ((K4, I, I, I, I, A, A, A, P), -_GK4 / 24.0),
                 ((K4, I, I, I, I, A, P), 3.0 * _GK4 / 24.0),
                 ((D, B), float(_GBK)),
                 ((K3, K3, I, I, I, I, I, I, A, A, A, A, A, P), -1.0 / 72.0),
                 ((K3, K3, I, I, I, I, I, I, A, A, A, P), 10.0 / 72.0),
                 ((K3, K3, I, I, I, I, I, I, A, P), -15.0 / 72.0)]
        degree = max(len(k) for k, _ in terms)
        S.update(n=n, one=fnp.ones(n, dtype=fnp.float64),
                 index=fnp.asarray([[(k[j] if j < len(k) else o) for k, _ in terms] for j in range(degree)]),
                 coefficient=fnp.asarray([float(c) for _, c in terms], dtype=fnp.float64))
    rows = hold(fnp.stack([S['one'], g, aux['alpha'], aux['pdf'],
                          hold(fnp.power(s, -1.0)), aux['pre_k3'], aux['pre_k4'], d, bpre]))
    _GQ33_STATS['calls'] += 1
    return S['coefficient'] @ hold(fnp.prod(hold(rows[S['index']]), axis=0))

def _gq33_predict(self, *args, **kwargs):
    _GQ33_STATS['calls'] = 0
    try:
        return _GQ33_PREDICT_PARENT(self, *args, **kwargs)
    finally:
        _ASTRA_COMPUTE_STATS['gate33'] = dict(_GQ33_STATS)

Estimator.predict = _gq33_predict

# Frozen public-shape padding reserve; actual0.12.3 prices in SCREEN_v1.json.
# Only local temporary arrays are introduced. Existing dispatcher cache policy stays parent-owned.
_O18PAD_RULES = {('mm', (672, 800, 6752)): (704, 832, 6784), ('mm', (736, 768, 6944)): (768, 768, 6976), ('mm', (736, 800, 6880)): (768, 832, 6912), ('mm', (768, 800, 6688)): (768, 832, 6720), ('mm', (832, 864, 6144)): (832, 896, 6144), ('mm', (832, 864, 7008)): (832, 896, 7040), ('mm', (832, 864, 8256)): (832, 896, 8256), ('mm', (896, 928, 5728)): (896, 1024, 5760), ('mm', (896, 928, 6304)): (896, 960, 6336), ('mm', (896, 928, 7936)): (896, 960, 7936), ('mm', (896, 928, 7968)): (896, 960, 8000), ('mm', (896, 928, 8000)): (896, 960, 8000), ('mm', (896, 928, 8032)): (896, 960, 8064), ('mm', (896, 928, 9888)): (896, 960, 9920), ('mm', (960, 928, 96)): (960, 960, 128), ('mm', (960, 928, 9824)): (960, 960, 9856), ('mm', (1024, 4096, 992)): (1024, 4096, 1024), ('shared_old384', (544, 384, 384)): (576, 384, 384)}
_O18PAD_PARENT_MM = _mm
_O18PAD_PARENT_SHARED = _shared_old384_mm
_O18PAD_PARENT_PREDICT = Estimator.predict
_O18PAD_BUSY = [False]
_O18PAD_STATS = dict(mm=0, shared=0, pad_elements=0, crop_elements=0)

def _o18pad_product(entry, parent, a, b):
    scope = _W5_PORT_SCOPE
    if (_O18PAD_BUSY[0] or not _WINOGRAD or not _AB_ON or _SCRATCH is None
            or _FAST_RESCUE_ON or _UBC_CONTEXT[0] is not None or _UBX_CTX[0] is not None
            or _ASTRA_CLUSTER_CTX[0] is not None or _UBX_RC[0] is not None
            or _ASTRA_RLF_CONTEXT[0] is not None
            or (scope is not None and scope.get('grant') is not None)
            or len(a.shape) != 2 or len(b.shape) != 2
            or a.dtype != 'float32' or b.dtype != 'float32'
            or int(a.shape[1]) != int(b.shape[0])):
        return parent(a, b)
    m, k, n = int(a.shape[0]), int(a.shape[1]), int(b.shape[1])
    dims = _O18PAD_RULES.get((entry, (m, k, n)))
    if dims is None:
        return parent(a, b)
    M, K, N = dims
    hold = _E2Hold()
    _O18PAD_BUSY[0] = True
    try:
        aa, bb = a, b
        if (M, K) != (m, k):
            aa = hold(fnp.zeros((M, K), dtype=fnp.float32))
            hold(fnp.copyto(hold(aa[:m, :k]), a))
            _O18PAD_STATS['pad_elements'] += M*K
        if (K, N) != (k, n):
            bb = hold(fnp.zeros((K, N), dtype=fnp.float32))
            hold(fnp.copyto(hold(bb[:k, :n]), b))
            _O18PAD_STATS['pad_elements'] += K*N
        answer = parent(aa, bb); hold.clear(); del aa, bb  # Owned product no longer needs padded inputs.
        if (M, N) != (m, n):
            hold(answer)
            answer = fnp.copy(hold(answer[:m, :n]))
            _O18PAD_STATS['crop_elements'] += m*n
        _O18PAD_STATS['mm' if entry == 'mm' else 'shared'] += 1
        return answer
    finally:
        _O18PAD_BUSY[0] = False

def _mm(a, b):
    return _o18pad_product('mm', _O18PAD_PARENT_MM, a, b)

def _shared_old384_mm(a, b):
    return _o18pad_product('shared_old384', _O18PAD_PARENT_SHARED, a, b)

def _o18pad_predict(self, *args, **kwargs):
    _O18PAD_STATS.update(mm=0, shared=0, pad_elements=0, crop_elements=0)
    try:
        return _O18PAD_PARENT_PREDICT(self, *args, **kwargs)
    finally:
        _O18PAD_BUSY[0] = False
        _ASTRA_COMPUTE_STATS['padding18'] = dict(_O18PAD_STATS)

Estimator.predict = _o18pad_predict


# JSYM18: remove numerical antisymmetry from the selected Gram block before QR.
# The selected rows are unique and sorted; all other rows of the owned Y stay intact.
_JSYM18_STATS = dict(calls=0, elements=0)
_JSYM18_PREDICT_PARENT = Estimator.predict

def _jsym18_landmark(Y, rows):
    hold = _E2Hold()
    selected = hold(fnp.take(Y, rows, axis=0))
    symmetric = hold(hold(selected + hold(selected.T)) * 0.5)
    hold(fnp.put_along_axis(Y, hold(rows[:, None]), symmetric, axis=0))
    _JSYM18_STATS['calls'] += 1
    _JSYM18_STATS['elements'] += int(selected.shape[0]) * int(selected.shape[1])

def _jsym18_predict(self, *args, **kwargs):
    _JSYM18_STATS.update(calls=0, elements=0)
    try:
        return _JSYM18_PREDICT_PARENT(self, *args, **kwargs)
    finally:
        _ASTRA_COMPUTE_STATS['jsk_landmark_symmetry18'] = dict(_JSYM18_STATS)

Estimator.predict = _jsym18_predict


