    _view, _kind, _L, r, c = got
    f = slice(None)
    quad = _LB3_BOX[(kind, L)]['quad'][(f,) * L + (slice(0, r),) + (f,) * L + (slice(0, c),)]
    _BH_HOLD.append(G)
    slot[0] = None; slot[1] = quad
    _L3_STATS['quads'] += 1
    _LB3_STATS['quad'] += 1
    return quad


